(window.GIM_TS=window.GIM_TS||{})["Bava Batra.12"]={"from":288,"a":[["\u0003ו\u0004עוד \u0003אמר ר' יהושע בן לוי\u0004 בתמיהה על פסוק זה \u0003: כל ימי עני רעים? והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003שבתות וימים טובים\u0004 שגם העניים נהנים בסעודתם ונחים בהם! ויש לתרץ \u0003כ\u0004דברי \u0003שמואל,\u0004 ש\u0003אמר שמואל: שנוי וסת\u0004 (הרגל) הוא \u0003תחלת חולי,\u0004 ולכן העני סובל גם בשבתות וימים טובים, משום שהוא משנה בהם מנהגו ואכילתו מבימות החול.","\u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003בספר בן סירא: \"כל ימי עני רעים\", בן סירא אומר: אף לילות\u0004 של העני רעים, \u0003בשפל גגים גגו,\u0004 מפני העוני גג ביתו נמוך יותר מגגות בתי כל העיר, ולכן \u0003ממטר גגים לגגו,\u0004 כל המטר שיורד על הגגות יורד בסוף על גגו שלו. ומצד שני, \u0003ברום הרים כרמו\u0004 כרמו של עני נמצא במקום הגבוה ביותר בהרים, שהוא המקום הרחוק והפחות טוב, ולכן הגשם סוחף \u0003מעפר כרמו לכרמים\u0004 האחרים. וכך נמצאים כל ימיו רעים אפילו בדברים אלה.","\u0003השולח סבלונות\u0004 (מתנות לכלה ולמשפחה) \u0003לבית חמיו\u0004 לאחר הקידושין, אם \u0003שלח שם\u0004 אפילו סכום של \u0003מאה מנה, ואכל שם\u0004 לאחר מכן \u0003סעודת חתן אפילו בדינר\u0004 אחד בלבד — \u0003אינן נגבין,\u0004 אין מחזירים אותם מאה דינרים למשפחת החתן, גם כאשר בטלו הנישואין מאיזה טעם. \u0003לא אכל שם סעודת חתן\u0004 — \u0003הרי אלו נגבין,\u0004 שאינם נחשבים כמתנה גמורה. \u0003שלח סבלונות מרובין\u0004 על מנת \u0003שיחזרו עמה לבית בעלה,\u0004 כלומר, כדי שהיא תיקח אתה את המתנות הללו לביתם המשותף — \u0003הרי אלו נגבין\u0004 אם הנישואים מתבטלים. שלח \u0003סבלונות מועטין\u0004 על מנת \u0003שתשתמש בהן בבית אביה\u0004 — \u0003אין נגבין.\u0004","על מה ששנינו שאם אכל בבית חמיו אפילו בדינר אין הסבלונות נגבים, \u0003אמר רבא:\u0004 זהו \u0003דוקא\u0004 שאכל בשווה \u0003דינר, אבל\u0004 אם אכל \u0003פחות מ\u0004שווה \u0003דינר\u0004 — \u0003לא.\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שכך הוא הדין, שהרי \u0003\"דינר\" תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]!\u0006 ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003הוא הדין\u0004 ש\u0003אפילו פחות מדינר\u0004 יהא בזה משום סעודה, \u0003והאי דקתני\u0004 \u0005[וזהו ששנה]\u0006 \u0003\"דינר\"\u0004 — \u0003אורחא דמילתא קתני\u0004 \u0005[דרך הרגילה שנה],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שצריך שתהא זו סעודה חשובה ששוויה לפחות דינר.","ומבררים את הדין האמור במשנה לפרטיו, מתוך דיוק בלשונה של המשנה. \u0003\"אכל\" תנן\u0004 \u0005[שנינו],\u0006 \u0003שתה מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 וכן אם \u0003הוא\u0004 עצמו אכל שם \u0003תנן\u0004 \u0005[שנינו],\u0006 \u0003שלוחו\u0004 שאכל \u0003מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 אם אכל \u0003שם\u0004 (בבית חמיו) \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 אם \u0003שגר\u0004 (שלח) \u0003לו\u0004 חותנו סעודה במתנה לביתו, \u0003מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא ושמע],\u0006 פתרון לדבר ממה ש\u0003אמר רב יהודה אמר שמואל: מעשה באדם אחד ששגר לבית חמיו מאה קרונות של כדי יין ושל כדי שמן ושל כלי כסף ושל כלי זהב ושל כלי מילת\u0004 (משי), \u0003ורכב בשמחתו, והלך ועמד על פתח בית חמיו, והוציאו\u0004 לו \u0003כוס של חמין\u0004 עבורו \u0003ושתה, ומת\u0004 לאחר מכן.","והיו דנים מה דינם של כל המתנות הללו, \u0003וזו הלכה העלה ר' אחא שר הבירה לפני חכמים לאושא\u0004 ששאל מה עושים במקרה זה, \u0003ואמרו: סבלונות העשוין ליבלות\u0004 — \u0003אין נגבין,\u0004 והם מתנה גמורה, \u0003ושאין עשוין ליבלות\u0004 — \u0003נגבין. שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003אפילו שתה\u0004 אין הסבלונות נגבים.","ומציעים: האם \u0003שמעת מינה\u0004 \u0005[למד אתה ממנה]\u0006 שאינם נגבים גם \u0003אפילו\u0004 אכל או שתה \u0003פחות מדינר?\u0004 שהרי אין כוס חמין שווה דינר. ודוחים, \u0003אמר רב אשי:\u0004 \u0003מאן לימא לן\u0004 \u0005[מי יאמר לנו]\u0006 ש\u0003לא\u0004 \u0003שחקי ליה מרגניתא דשויא אלפא זוזי ואשקיה\u0004 \u0005[שחקו לו מרגלית ששוה אלף זוז לתוך כוס החמין והשקו אותו]\u0006\u0005?\u0006 ואין איפוא להוכיח מכאן לגבי פחות מדינר. ועוד מציעים: \u0003שמעת מינה\u0004 \u0005[למד אתה מכאן]\u0006 ש\u0003אפילו שגרו לו\u0004 סעודה מבית חמיו — אין מחזירים את הסבלונות? שהרי אמרו שהיה בפתח בית חמיו, ולא נכנס פנימה! ודוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003כל פתח בית חמיו כבית חמיו דמי\u0004 \u0005[נחשב].\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003מהו שישלש?\u0004 כלומר, אם אכל בפחות מדינר, האם מחלקים ואומרים שגם הסבלונות חוזרים לפי ערך הכמות שאכל או שתה? ועוד, \u0003שבח סבלונות\u0004 אם השביחו הסבלונות במשך הזמן, בכמות או במחיר, \u0003מהו?\u0004 האם כשמחזירים את הסבלונות צריך להחזיר גם את השבח? והצדדים בשאלה: \u0003כיון דאי איתנהו\u0004 \u0005[שאם\u0006 היו \u0005מצויים]\u0006 — \u0003לדידיה הדרי\u0004 \u0005[אליו\u0006 היו \u0005חוזרים],\u0006 אם כן, \u0003ברשותיה שבוח\u0004 \u0005[ברשותו השביחו],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דאי אבדי\u0004 \u0005[שאם\u0006 היו \u0005אובדים],\u0006 \u0003או מגנבי\u0004 \u0005[נגנבים]\u0006 \u0003בעי שלומי ליה\u0004 \u0005[צריך\u0006 היה צד הכלה \u0005לשלם לו]\u0006 לפיכך — \u0003ברשותא דידה שבוח\u0004 \u0005[ברשות שלה השביחו]?\u0006 שאלה זו לא נפתרה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: סבלונות העשוין ליבלות\u0004 שאינם נגבים \u0003ולא בלו, מהו\u0004 דינם? האם צריך להחזירם, כמו סבלונות שאינם עשויים ליבלות? ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר מלשון הברייתא: \u0003וזו הלכה העלה ר' אחא שר הבירה לפני חכמים באושא, ואמרו: סבלונות העשוין ליבלות\u0004 — \u0003אין נגבין, ושאין עשוין ליבלות\u0004 — \u0003נגבין.\u0004 ונדייק: \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 הכוונה שאם עשויים להיבלות אין נגבים \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא בלו?\u0004 שהרי לא חילקה הברייתא בדבר. ודוחים: \u0003לא,\u0004 מדובר שם דווקא ש\u0003בלו.\u0004","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון אחר לדבר ממה ששנינו במשנתנו: \u0003סבלונות מועטין שתשתמש בהן והיא בבית אביה\u0004 — \u0003אין נגבין,\u0004 ומשמע שהדין כן בכל מקרה, ואין מקפידים אם בלו או לא בלו! \u0003תרגמה\u0004 \u0005[הסביר אותה]\u0006 \u0003רבא: בייבא וסבכתא\u0004 \u0005[בגדים זולים]\u0006 שבוודאי מוחל עליהם.","ועוד בענייני סבלונות \u0003אמר רב יהודה אמר רב: מעשה באדם אחד ששגר לבית חמיו יין חדש ושמן חדש וכלי פשתן חדש בעצרת\u0004 (חג השבועות). ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בסיפור זה? ומשיבים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]:\u0006 \u0003חשיבותא\u0004 \u0005[חשיבותה]\u0006 של \u0003ארץ ישראל קא משמע לן\u0004 \u0005[השמיע לנו\u0006 בכך\u0005],\u0006 שכבר בחג השבועות מצויים בה יין ושמן וכלי פשתן חדשים, אף שהיא עונה מוקדמת של השנה. \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003דאי טעין\u0004 \u0005[שאם\u0006 החתן \u0005טוען]\u0006 ששלח דברים אלה בזמן זה — אין אומרים שהוא דבר בלתי אפשרי, אלא \u0003טענתיה\u0004 \u0005[טענתו]\u0006 \u0003טענה.\u0004","ואגב הדברים מביאים מעשה נוסף ש\u0003אמר רב יהודה אמר רב: מעשה באדם אחד שאמרו לו\u0004 ש\u0003אשתו\u0004 ארוסתו \u0003תותרנית היא,\u0004 שאינה יכולה להריח, \u0003ונכנס אחריה לחורבה לבודקה\u0004 אם באמת תותרנית היא, \u0003אמר לה: ריח צנון אני מריח בגליל,\u0004 שלקח עימו תמר ואמר לה שהוא מריח ריח צנון, ורצה לנסותה אם היא מריחה ריח זה."],["\u0003אמרה ליה\u0004 \u0005[לו]\u0006 בצחוק: \u0003מן יהיב לן\u0004 \u0005[מי יתן לנו]\u0006 \u0003מכותבות\u0004 (תמרים) של \u0003יריחו ואכלנא ביה\u0004 \u0005[ואוכל אותם],\u0006 שרמזה בכך שהיא מריחה ריח התמר שהיה עימו. \u0003נפל עלה\u0004 \u0005[עליה]\u0006 ה\u0003חורבה ומתה. אמרו חכמים: הואיל ולא נכנס אחריה אלא לבודקה\u0004 ולא לשם יחוד וביאה, אם \u0003מתה\u0004 — \u0003אינו יורשה,\u0004 שלא נגמרו הנישואין, ואין אדם יורש את ארוסתו.","שנינו במשנה ש\u0003סבלונות מועטין שתשתמש בהן בבית אביה\u0004 — אינם חוזרים. \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רבין סבא\u0004 \u0005[הזקן]\u0006 \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רב פפא ויתיב וקאמר\u0004 \u0005[ויושב היה ואומר]:\u0006 \u0003בין שמתה היא ובין שמת הוא,\u0004 ובין אם \u0003הדר\u0004 \u0005[חזר]\u0006 \u0003הוא\u0004 בו מן הקידושין — \u0003סבלונות\u0004 (מתנות) שנתן — \u0003הדרי\u0004 \u0005[חוזרים],\u0006 \u0003מאכל ומשתה\u0004 שנתן — \u0003לא הדר\u0004 \u0005[חזר].\u0006 אם \u0003הדרא\u0004 \u0005[חזרה]\u0006 \u0003בה איהי\u0004 \u0005[היא]\u0006 — \u0003הדרא\u0004 \u0005[מחזירה]\u0006 \u0003אפילו כישא דירקא\u0004 \u0005[אגודת ירק]\u0006 שנתן למשפחה. \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: ו\u0004במקרה שמחזירים, \u0003שמין להן\u0004 למשפחת הכלה \u0003דמי בשר בזול,\u0004 ולא כמחיר שהוא שילם. ושואלים: \u0003עד כמה,\u0004 מה נקרא דמי בשר \u0003בזול?\u0004 ומשיבים: \u0003עד תילתא\u0004 \u0005[שליש]\u0006 פחות מהמחיר ששילם עבורו.","\u0003שכיב מרע שכתב\u0004 בצוואתו \u0003כל נכסיו\u0004 כמתנה \u0003לאחרים, ושייר קרקע כל שהוא\u0004 לעצמו — \u0003מתנתו קיימת\u0004 גם אם אחר כך הבריא. שכיון שהשאיר קרקע לעצמו לפרנסתו הרי זה מורה שנתן את שאר הדברים כמתנה גמורה בחייו. אבל אם \u0003לא שייר\u0004 לעצמו \u0003קרקע כל שהוא\u0004 והבריא — \u0003אין מתנתו קיימת\u0004 שברור מכאן שדעתו היתה שהוא מת, ואילו היה יודע שיקום מחוליו לא היה נותן כלום.","ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור \u0003דאזלינן בתר אומדנא\u0004 \u0005[שאנו הולכים אחר הערכה]\u0006 של דעתו של אדם, אף על פי שלא פירש את הדברים? \u0003אמר רב נחמן:\u0004 שיטת \u0003ר' שמעון בן מנסיא היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהלך בנו למדינת הים, ושמע שמת בנו, ועמד וכתב כל נכסיו לאחר, ואחר כך בא בנו\u0004 — \u0003מתנתו\u0004 מכל מקום הריהי \u0003מתנה,\u0004 שהרי מדעת שלימה נתן. \u0003ר' שמעון בן מנסיא אומר: אין מתנתו מתנה, שאלמלא\u0004 (אילו) \u0003היה יודע שבנו קיים\u0004 — \u0003לא היה כותבן,\u0004 משמע שר' שמעון בן מנסיא הולך אחר אומדן דעתו של אדם.","\u0003רב ששת אמר:\u0004 משנתנו, שיטת \u0003ר' שמעון שזורי היא\u0004 שהולך אחר אומדנא, כיצד? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003בראשונה היו\u0004 חכמים \u0003אומרים: היוצא בקולר\u0004 (שרשרת שהיו מוציאים בה את היוצאים להיהרג) \u0003ואמר \"כתבו גט לאשתי\"\u0004 — אין מדקדקים בדבריו שלא אמר במפורש שגם יתנו לה את הגט (שאילו סתם אדם שאומר \"כתבו גט לאשתי\" — כותבים אך אין נותנים), אלא \u0003הרי אלו יכתבו ויתנו,\u0004 לפי שדעתו היתה שיפטרו אותה מחובת היבום והחליצה. \u0003חזרו\u0004 חכמים \u0003לומר\u0004 לאחר מכן: \u0003אף המפרש\u0004 היוצא לים, \u0003והיוצא בשיירא,\u0004 שאמרו \"כתבו\" — כותבים ונותנים עבורם. \u0003ר' שמעון שזורי אומר: אף המסוכן,\u0004 כלומר, חולה מסוכן שאמר \"כתבו\", מניחים שחשב שהוא עומד למות, ונתכוון לגרשה, אלא שלא סיים את דבריו כראוי.","ושואלים: \u0003ורב נחמן מאי טעמא לא מוקים לה\u0004 \u0005[מה טעם אינו מעמיד אותה,\u0006 את משנתנו\u0005]\u0006 \u0003כר' שמעון שזורי?\u0004 ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 ש\u0003אמר \"כתבו\",\u0004 שמכל מקום פירש מקצת דבריו. ואילו במשנתנו, כשלא שייר קרקע — לא אמר דבר על הכוונה המיוחסת לו. ושואלים מצד שני: \u0003ורב ששת מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא מוקים לה\u0004 \u0005[מעמיד אותה\u0006 את המשנה\u0005]\u0006 \u0003כר' שמעון בן מנסיא?\u0004 ומשיבים: \u0003אומדנא דמוכח שאני\u0004 \u0005[הערכה מוכחת\u0006 כגון זו שדיבר עליה היא \u0005שונה],\u0006 אבל במקום שאין הדברים מוכחים כל כך — שמא אין הולכים אחר הערכה.","ושואלים: \u0003מאן תנא להא דתנו רבנן\u0004 \u0005[מי שנה את זו ששנו חכמים]:\u0006 \u0003הרי שהיה חולה ומוטל במטה, ואמרו לו: נכסיך למי? ואמר להן\u0004 החולה:"],["\u0003דומה\u0004 (חשבתי) עד עכשיו \u0003שיש לי בן, עכשיו\u0004 שנודע לי \u0003שאין לי בן\u0004 — \u0003נכסי לפלוני;\u0004 וכן אם \u0003היה חולה ומוטל במטה, ואמרו לו: נכסיו למי? אמר להן: דומה שאשתי מעוברת, עכשיו שאין אשתי מעוברת\u0004 — \u0003נכסי לפלוני, ו\u0004לאחר מכן \u0003נודע שיש לו בן או שהיתה אשתו מעוברת\u0004 — \u0003אין מתנתו מתנה,\u0004 שהרי מדבריו ניכר שאינו נותן את המתנה אלא משום כך.","ומציעים: \u0003לימא\u0004 \u0005[האם לומר]\u0006 כי שיטת \u0003ר' שמעון בן מנסיא היא ולא רבנן\u0004 \u0005[חכמים]?\u0006 ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 לשון \u0003\"דומה\" שאני\u0004 \u0005[שונה],\u0006 שהרי כאן לא נתן מתנה סתם, אלא פירש ואמר טעמו של דבר.","ותוהים: ובאמת \u0003ודקארי לה מאי קארי לה\u0004 \u0005[וזה שהקשה אותה מה הקשה אותה]?\u0006 הרי בבירור רואים את ההבדל בין המקרים! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003צעריה\u0004 \u0005[צערו]\u0006 \u0003הוא דקא מדכר\u0004 \u0005[שהוא מזכיר],\u0006 שאינו בא לומר מפני מה הוא נותן מתנה זו, אלא מאחר שהוא מדבר על ירושתו הריהו מזכיר את צערו על שאין לו בן, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבאמירתו זו בוודאי גילה שזה הוא הטעם שהוא נותן מתנה לזרים, ואם יש לו בן — הרי הוא מקבל את הנכסים.","\u0003אמר ר' זירא אמר רב: מנין למתנת שכיב מרע שהיא מן התורה?\u0004 — \u0003שנאמר\u0004 בפרשת הירושה \u0003: \"\u0004איש כי ימות ובן אין לו \u0003והעברתם את נחלתו לבתו\"\u0004 (במדבר כז, ח), ולשון זו של \"העברה\" מיותרת, שהרי ממילא נחלתו עוברת לבת. אלא בא הדבר ללמד כי \u0003יש לך העברה אחרת\u0004 של נכסים \u0003שהיא כזו,\u0004 הנעשית בלא מעשה הקנאה, כמו נחלה העוברת ליורש, \u0003ואי זו?\u0004 — \u0003זו מתנת שכיב מרע.\u0004","\u0003רב נחמן אמר רבה בר אבוה, מהכא\u0004 \u0005[מכאן]\u0006 אפשר להביא ראיה למתנת שכיב מרע, שנאמר: \u0003\"\u0004ואם אין לו בת \u0003ונתתם את נחלתו לאחיו\"\u0004 (במדבר כז, ט), והרי הנחלה ממילא עוברת! אלא ללמד כי \u0003יש לך נתינה אחרת שהיא כזו, ואי זו?\u0004 — \u0003זו מתנת שכיב מרע.\u0004","ושואלים: \u0003ורב נחמן מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר\u0004 שנלמד הדבר \u0003מ\"והעברתם\"\u0004 כדרך שאמר ר' זירא? ומשיבים: \u0003ההוא מיבעי ליה\u0004 \u0005[אותו\u0006 כתוב \u0005נצרך לו]\u0006 \u0003לכ\u0004 מו שאמר \u0003רבי, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אומר: בכולן\u0004 (בשאר דיני הירושה) \u0003נאמרה בהן\u0004 לשון \u0003\"נתינה\"\u0004 (\"ונתתם\") \u0003וכאן\u0004 בבת \u0003נאמרה\u0004 לשון \u0003\"העברה\",\u0004 לומר ש\u0003אין לך שמעביר נחלה משבט לשבט אלא בת,\u0004 ומדוע? \u0003הואיל ובנה ובעלה יורשין אותה\u0004 והם עשויים להיות משבט אחר.","ושואלים לצד האחר: \u0003ור' זירא מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר\u0004 שנלמדת מתנת שכיב מרע \u0003מ\"ונתתם\"?\u0004 ומשיבים: לדעתו מכאן אין ללמוד, משום ש\u0003אורחיה דקרא\u0004 \u0005[דרכו של הכתוב]\u0006 \u0003הוא\u0004 לכתוב כך.","\u0003רב מנשיא בר ירמיה אמר, מהכא\u0004 \u0005[מכאן]\u0006 יש ראיה: \u0003\"בימים ההם חלה חזקיהו למות ויבא אליו ישעיהו בן אמוץ הנביא ויאמר אליו כה אמר ה' צו לביתך כי מת אתה ולא תחיה\"\u0004 (מלכים ב כ, א), משמע ש\u0003בצואה בעלמא\u0004 \u0005[בלבד]\u0006 יכול אדם להעביר את נכסיו לאחר מותו.","\u0003רמי בר יחזקאל אמר, מהכא\u0004 \u0005[מכאן],\u0006 שנאמר: \u0003\"ואחיתפל ראה כי לא נעשתה עצתו ויחבש את החמור\u0004 ויקם \u0003וילך אל ביתו אל עירו ויצו אל ביתו ויחנק\"\u0004 (שמואל ב יז, כג), ללמדנו מכאן שדי \u0003בצואה בעלמא\u0004 \u0005[בלבד]\u0006 ואינו צריך לקנין.","אגב הזכרת צוואתו של אחיתופל, מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים],\u0006 \u0003שלשה דברים צוה אחיתופל את בניו\u0004 לפני מותו, לאחר שראה כי מרד אבשלום בדוד נכשל \u0003: אל תהיו\u0004 שותפים \u0003במחלוקת, ואל תמרדו במלכות בית דוד, ו\u0004אם \u0003יום טוב של עצרת\u0004 (חג שבועות) \u0003ברור,\u0004 כלומר, יום בהיר, לא מעונן — \u0003זרעו חטים,\u0004 שהוא סימן שתהיה באותה שנה הצלחה לגידול החיטה. \u0003מר זוטרא אמר: \"\u0004יום \u0003בלול\" איתמר\u0004 \u0005[נאמר],\u0006 והכוונה היא להיפך, שכאשר יום טוב של עצרת הוא מעונן זהו סימן טוב לחיטי השנה הבאה. \u0003אמרי נהרדעי משמיה\u0004 \u0005[אמרו\u0006 חכמי \u0005נהרדעא משמו]\u0006 של \u0003ר' יעקב:\u0004 בין לנוסח זה ובין לנוסח זה \u0003לא\u0004 \u0003\"ברור\"\u0004 — \u0003ברור ממש, ולא \"בלול\"\u0004 — \u0003בלול ממש, אלא אפילו\u0004 היה \u0003בלול ורוח צפונית מנשבתו\u0004 — \u0003זה הוא \"ברור\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לרב אשי: אנן\u0004 \u0005[אנו]\u0006 את עניין הסימנים על טיב התבואות של השנה הבאה, על מה שאמר \u0003רב יצחק בר אבדימי מתנינן לה\u0004 \u0005[שונים אנו אותה],\u0006 סומכים אנו, ש\u0003אמר רב יצחק בר אבדימי: מוצאי יום טוב האחרון של חג\u0004 הסוכות \u0003הכל צופין ל\u0004עבר \u0003עשן המערכה\u0004 בבית המקדש, שמוצאים בו סימן לעתיד, אם \u0003נטה כלפי צפון\u0004 (שיש רוח דרומית) — \u0003עניים שמחים ובעלי בתים עצבין, מפני\u0004 שסימן הוא \u0003שגשמי שנה מרובין ופירות מרקיבין\u0004 מריבוי הגשמים, ואי אפשר לאחסן אותם. ולכן העניים שמחים — שיוזלו מחירי היבולים, ובעלי הבתים עצבים, מפני שיצטרכו להיפטר מכל היבול הגדול במהירות רבה ובמחיל מוזל.","אם \u0003נטה\u0004 עשן המערכה \u0003כלפי דרום\u0004 (מפני רוח צפונית) — \u0003עניים עצבים ובעלי בתים שמחין, מפני שגשמי שנה מועטין\u0004 ואין תבואה מרובה, \u0003ו\u0004מצד אחר \u0003ה\u0004\u0003פירות משתמרין,\u0004 ובעלי הפירות יכולים להעלות את מחיר התבואה ולהרויח. \u0003נטה כלפי מזרח\u0004 (מפני רוח מערבית) — \u0003הכל שמחין.\u0004 נטה \u0003כלפי מערב\u0004 (מפני רוח מזרחית) — \u0003הכל עצבין,\u0004 מפני שסימן שתהא זו שנת בצורת.","\u0003ורמינהי\u0004 \u0005[ומקשים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו בברייתא: רוח \u0003מזרחית\u0004 — \u0003לעולם יפה, מערבית\u0004 — \u0003לעולם קשה, רוח צפונית\u0004 — \u0003יפה לחטים בשעה שהביאו שליש\u0004 בישולם, \u0003וקשה לזיתים בשעה שיניצו\u0004 כשהם מוציאים פרחים, \u0003ורוח דרומית\u0004 — \u0003קשה לחטין בשעה שהביאו שליש, ויפה לזיתים בשעה שיניצו.\u0004","\u0003ואמר רב יוסף, ואיתימא\u0004 \u0005[ויש אומרים\u0006 שאמר\u0005]\u0006 \u0003מר זוטרא, ואיתימא\u0004 \u0005[ויש אומרים\u0006 שאמר\u0005]\u0006 \u0003רב נחמן בר יצחק: וסימנך,\u0004 שתדע למה יפות הרוחות הצפונית והדרומית — הכלים שבמקדש, \u0003שלחן בצפון ומנורה בדרום, האי מרבי דידיה והאי מרבי דידיה\u0004 \u0005[זה מגדל\u0006 את \u0005שלו וזה מגדל\u0006 את \u0005שלו],\u0006 שהשולחן שיש שעליו לחם חיטים עומד בצפון, וסימן הוא שרוח צפונית יפה לחיטים. ומנורה שבה מדליקים שמן זית היא בדרום, ורוח דרומית יפה לה. ומכל מקום נאמר בתחילת הברייתא שרוח מזרחית יפה ומערבית קשה — היפך הדברים בברייתא הקודמת!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא לן והא להו\u0004 \u0005[זה לנו,\u0006 לבני בבל, טובה יותר הרוח המזרחית, \u0005וזה להם,\u0006 לבני ארץ ישראל\u0005]\u0006 שהארץ יבשה וצריכים שם יותר גשמים, והם באים עם הרוח המערבית.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אבא שאול אומר: יום טוב של עצרת ברור\u0004 — \u0003סימן יפה לכל השנה כולה. אמר רב זביד: האי יומא קמא דריש שתא\u0004 \u0005[היום הראשון של ראש השנה],\u0006 \u0003אי חמים\u0004 \u0005[אם\u0006 הוא \u0005חם]\u0006 — \u0003כולה שתא חמימא\u0004 \u0005[כל השנה\u0006 תהיה \u0005חמה],\u0006 \u0003אי קריר\u0004 \u0005[אם\u0006 הוא \u0005קר]\u0006 — \u0003כולה שתא קרירא\u0004 \u0005[כל השנה\u0006 תהיה \u0005קרה].\u0006 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה],\u0006 מה יכול אדם לעשות לגבי מזג האויר?"],["ומשיבים: \u0003לתפלתו של כהן גדול\u0004 שהיה מתפלל ביום הכיפורים על מזג האויר של השנה, ולפי מה שרואה בראש השנה ידע כיצד לכוון בתפילתו.","ושבים לעיקר הענין, שהבאנו ראיות מן הכתובים לקיומה של מתנת שכיב מרע. \u0003ורבא אמר\u0004 בשם \u0003רב נחמן: מתנת שכיב מרע מדרבנן בעלמא\u0004 \u0005[מדברי חכמים בלבד]\u0006 \u0003היא\u0004\u0003,\u0004 והטעם שתיקנו חכמים דבר זה — \u0003שמא תטרף דעתו עליו,\u0004 שכאשר החולה יראה שמתמהמהים בעשיית רצונו, עד שיכתבו ויעשו את כל הנתינה כדין — עלולה דעתו להיטרף עליו.","ושואלים: \u0003ומי\u0004 \u0005[והאם]\u0006 \u0003אמר רב נחמן הכי\u0004 \u0005[כך]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב נחמן, אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003אמר שמואל: המוכר שטר חוב לחבירו, וחזר\u0004 אחר כך המוכר \u0003ומחלו\u0004 ללווה את חובו — הרי זה \u0003מחול\u0004 ונפקע השטר, \u0003ואפילו יורש מוחל\u0004 על חוב שבשטר שמכר מורישו לאחר. מכל מקום \u0003מודה שמואל, שאם נתנו\u0004 את השטר הזה \u0003במתנת שכיב מרע,\u0004 ש\u0003אינו יכול למוחלו;\u0004 ומעתה,","\u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שמתנת שכיב מרע היא \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003אינו יכול למחול,\u0004 שאין בכוח היורש למחול דבר שכבר הוקנה לאחר. \u0003אלא אי אמרת דרבנן\u0004 \u0005[אם אתה אומר שמדברי חכמים]\u0006 \u0003היא, אמאי\u0004 \u0005[מדוע]\u0006 \u0003אינו יכול למחול?\u0004 יהא זה כשאר שטרי החוב! ודוחים: סבור רב נחמן שאמנם מתנת שכיב מרע \u0003אינה של תורה,\u0004 \u0003ו\u0004אולם \u0003עשאוה\u0004 חכמים תקיפה וחזקה \u0003כשל תורה.\u0004","\u0003אמר רבא אמר רב נחמן: שכיב מרע שאמר \"ידור פלוני בבית זה\",\u0004 או \u0003\"יאכל פלוני פירות דקל זה\"\u0004 — \u0003לא אמר כלום,\u0004 שאינו יכול לתת דבר שאינו ממשי, כשימוש בנכסים, או באכילת פירות שעדיין לא צמחו, \u0003עד שיאמר \"תנו בית זה לפלוני וידור בו\",\u0004 או \u0003\"תנו דקל זה לפלוני ויאכל פירותיו\".\u0004","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 ש\u0003סבר רב נחמן\u0004 כי דווקא \u0003מילתא דאיתא\u0004 \u0005[דבר שישנו]\u0006 \u0003בבריא\u0004 שניתן להקנותו במתנת בריא, \u0003איתא\u0004 \u0005[ישנו]\u0006 גם \u0003בשכיב מרע\u0004 באמירה בלבד, אבל דבר \u0003דליתא\u0004 \u0005[שאינו]\u0006 יכול להיות מוקנה \u0003בבריא ליתא\u0004 \u0005[אינו]\u0006 \u0003בשכיב מרע,\u0004 ומשום כך, כיון שאין אדם בריא יכול להקנות לחבירו דבר שאין בו ממש, כך גם שכיב מרע אינו יכול לעשות זאת באמירה? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר רבא אמר רב נחמן:\u0004"],["\u0003שכיב מרע שאמר \"תנו\u0004 במתנה \u0003הלואתי\u0004 (ממון שחייב לי פלוני זה) \u0003לפלוני\u0004 אחר \u0003\"\u0004— עושים כדבריו ו\u0003הלואתו\u0004 ניתנת \u0003לפלוני, ואף על גב דליתיה\u0004 \u0005[ואף על פי שאינו],\u0006 שאין דבר כזה \u0003בבריא,\u0004 שאין בריא יכול להעביר הלוואה לאחר באמירה בלבד! \u0003רב פפא אמר:\u0004 שונה דין הלוואה שיכול שכיב מרע להעבירה באמירה בלבד, \u0003הואיל ויורש\u0004 של המת \u0003יורשה,\u0004 והרי חכמים נתנו למתנת שכיב מרע תוקף של ירושה.","\u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא אמר: הלואה איתא\u0004 \u0005[ישנה]\u0006 גם \u0003בבריא\u0004 באופן דומה, \u0003וכ\u0004דברי \u0003רב הונא אמר רב,\u0004 ש\u0003אמר רב הונא אמר רב:\u0004 האומר לחבירו \u0003\"\u0004אותו \u0003מנה\u0004 שיש \u0003לי בידך,\u0004 שאתה חייב לי, \u0003תנהו לפלוני\",\u0004 אם היה הדבר \u0003במעמד שלשתן\u0004 — המלוה, הלווה ומקבל המתנה — \u0003קנה\u0004 הפלוני, ואין צריך לעשות מעשה קנין מיוחד.","בהמשך לבירור בענין מי שנתן לחבירו אכילת פירות דקל בלבד, שאין חבירו קונה, אלא אם הקנה לו בגוף הדקל, \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 נתן אדם \u0003דקל לאחד ופירותיו לאחר,\u0004 \u0003מהו\u0004 הדין? \u0003מי\u0004 \u0005[האם]\u0006 \u0003שייר\u0004 במתנה מעין זו את \u0003מקום פירי\u0004 \u0005[הפירות],\u0006 ונתן לשני דבר הנמצא בעולם, וממילא קונה גם את הפירות שיגדלו שם, \u0003או לא שייר\u0004 ולא הקנה לו דבר. ובהמשך לבעיה זו, \u0003אם תמצי\u0004 \u0005[תמצא]\u0006 \u0003לומר:\u0004 שכל שנותן פירות \u0003לאחר לא הוי\u0004 \u0005[אין זה]\u0006 \u0003שיור\u0004 של מקום הפירות עד שיאמר בפירוש, יש לשאול: אם שייר את הפירות \u0003לעצמו,\u0004 שאמר \u0003\"\u0004הדקל נתון לך \u0003חוץ מפירותיו\", מהו?\u0004","בתשובה לכך \u0003אמר רבא אמר רב נחמן:\u0004 גם \u0003אם תמצי\u0004 \u0005[תמצא]\u0006 \u0003לומר\u0004 ותחליט ש\u0003דקל לאחד ופירותיו לאחר לא הוי\u0004 \u0005[אינו]\u0006 מתכוון לעשות \u0003שיור\u0004 את \u0003מקום פירי\u0004 \u0005[הפירות],\u0006 הרי אם נתן \u0003דקל לאחד ושייר פירותיו לפניו\u0004 (לעצמו) — \u0003שייר מקום פירי\u0004 \u0005[הפירות],\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל בין אם משייר פירות לאחר או לעצמו? — \u0003כל\u0004 דבר שהוא שייך \u0003לגבי נפשיה\u0004 \u0005[לעצמו]\u0006 — \u0003בעין יפה משייר,\u0004 ובוודאי הניח לעצמו לא רק את הפירות, אלא גם את מקום הפירות.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לרב אשי: אנן\u0004 \u0005[אנו]\u0006 על דברי \u0003ר' שמעון בן לקיש מתנינן לה\u0004 \u0005[שונים אנו אותה]\u0006 את דברי רבא בשם רב נחמן, שאדם משייר לעצמו בעין יפה, ומשם אנו למדים לענייננו. ש\u0003אמר ר' שמעון בן לקיש: המוכר בית לחבירו, ואמר לו\u0004 לקונה: \u0003\"על מנת שדיוטא העליונה שלי\"\u0004 — \u0003דיוטא העליונה\u0004 נשארת \u0003שלו.\u0004"],["ועל כך \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 אם מכר \u0003בית ל\u0004אדם \u0003אחד ודיוטא ל\u0004אדם \u0003אחד, מהו? מי הוי\u0004 \u0005[האם יש בכך]\u0006 \u0003שיור\u0004 זכויות נוספות לשני, מעבר לדיוטא עצמה, \u0003או לא? אם תמצא לומר\u0004 כי במקרה של \u0003בית לאחד ודיוטא לאחד לא הוי\u0004 \u0005[אין זה]\u0006 \u0003שיור,\u0004 יש לשאול: אם מכר בית ופירש \u0003\"חוץ מדיוטא\",\u0004 שהיא נשארת ביד המוכר, \u0003מהו?\u0004 האם לעצמו שייר?","בתשובה לכך \u0003אמר רבא אמר רב נחמן, אם תמצא לומר\u0004 כי \u0003בית לאחד ודיוטא לאחד לא הוי\u0004 \u0005[אין זה]\u0006 \u0003שיור,\u0004 אם מכר לאחד ואמר \u0003\"חוץ מדיוטא\" הוי\u0004 \u0005[הרי זה]\u0006 \u0003שיור.\u0004 ומוסיפים: \u0003ו\u0004כל זה הוא \u0003אליבא\u0004 \u0005[לפי\u0006 הסברו\u0005]\u0006 של \u0003רב זביד\u0004 לדברי ריש לקיש, ש\u0003אמר\u0004 שאם משייר את הדיוטא לעצמו מובנו \u0003שאם רצה להוציא בה זיזין\u0004 מן הדיוטא אל החצר — \u0003מוציא.\u0004","\u0003אלמא\u0004 \u0005[מכאן]\u0006 אנו מסיקים ש\u0003כיון\u0004 ש\u0003שייר דיוטא\u0004 — \u0003מקום זיזין נמי\u0004 \u0005[גם כן]\u0006 \u0003שייר.\u0004 \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין דקל ופירותיו, יש להסיק לדרך זו ש\u0003כיון\u0004 ש\u0003אמר\u0004 לגבי אילן \u0003\"חוץ מפירותיו\"\u0004 — \u0003מקום פירי\u0004 \u0005[הפירות]\u0006 \u0003שייר\u0004 גם כן לעצמו.","ובענין ששנינו במשנתנו, ששכיב מרע שכתב כל נכסיו ועמד מחוליו, אם שייר קרקע כלשהי — מתנתו קיימת, ואם לא — אין מתנתו קיימת, \u0003אמר רב יוסף בר מניומי אמר רב נחמן: שכיב מרע שכתב כל נכסיו לאחרים\u0004 — \u0003רואין: אם במחלק,\u0004 כלומר, כאשר נראה שהוא רוצה לחלק את כל נכסיו, הרי אם \u0003מת\u0004 — \u0003קנו כולן,\u0004 כל אלה שנתן להם נכסיו. והואיל וציווה את כל נכסיו, ולא שייר דבר לעצמו, לפיכך אם \u0003עמד\u0004 מחוליו — \u0003חוזר בכולן,\u0004 כדין המשנה, שהרי מסתבר שלא נתן כל אלה אלא מפני שחשב שהוא הולך למות.","ו\u0003אם בנמלך,\u0004 שנראה שהוא חושב מה לעשות בנכסיו, שנתן חלק ושייר ורק לאחר מכן נתן עוד לאדם אחר, הרי אם \u0003מת\u0004 — \u0003קנו כולן,\u0004 אבל במקרה זה, אם \u0003עמד\u0004 מחוליו — \u0003אינו חוזר אלא באחרון.\u0004 לפי שבכל הקודמים לאחרון שייר מנכסיו, ולפיכך מתנתם קיימת, ורק כאשר נתן לאחרון — לא שייר עוד בידו מאומה. \u0003ו\u0004מקשים: מדוע אנו אומרים בנמלך שנתן כל מתנה לעצמה? \u0003דלמא\u0004 \u0005[שמא]\u0006 כוונתו לתת הכל, וכשהוא בא לחלק \u0003עיוני קא מעיין והדר יהיב\u0004 \u0005[מעיין,\u0006 חושב הוא למי לתת \u0005ואחר כך נותן]!\u0006 ומשיבים: \u0003סתמיה\u0004 \u0005[סתמו]\u0006 של \u0003שכיב מרע מידק דייק והדר יהיב\u0004 \u0005[מדייק\u0006 היטב \u0005ו\u0006רק \u0005אחר כך נותן],\u0006 שהרי הוא יודע שמתנה זו היא לעולם. ואם רואים אנו בו שהוא מהרהר וחושב בין נתינה לנתינה — משמע שלא נתכוון לתת כל נכסיו מתחילה.","\u0003אמר רב אחא בר מניומי אמר רב נחמן: שכיב מרע שכתב כל נכסיו\u0004 הידועים לנו \u0003לאחרים,\u0004 \u0003ו\u0004אחר כך \u0003עמד\u0004 (הבריא) מחוליו — \u0003אינו חוזר, חיישינן\u0004 \u0005[חוששים אנו]\u0006 \u0003שמא יש לו נכסים במדינה אחרת,\u0004 ונמצא שנתן רק מקצת נכסיו ולא כולם, ובמתנה במקצת — אינו חוזר.","ותוהים: \u0003ואלא מתניתין דקתני\u0004 \u0005[משנתנו ששנה\u0006 בה\u0005]:\u0006 \u0003לא שייר קרקע כל שהוא\u0004 — \u0003אין מתנתו קיימת,\u0004 אם כן \u0003היכי משכחת לה\u0004 \u0005[איך אתה מוצא אותה]?\u0006 הרי תמיד יש לחשוש שמא יש לו קרקע במדינה אחרת! \u0003אמר רב חמא:\u0004 במשנה מדובר \u0003באומר\u0004 במפורש \u0003\"כל נכסי\u0004 נתונים לפלוני \u0003\",\u0004 ובהכרח לא נשאר בידו דבר. \u0003מר בר רב אשי אמר:\u0004 במשנתנו מדובר \u0003ב\u0004אופן ש\u0003מוחזק לן דלית ליה\u0004 \u0005[לנו שאין לו]\u0006 נכסים במקום אחר.","ובקשר למי ששייר מקצת נכסיו \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו: \u0003חזרה במקצת,\u0004 כשנתן שכיב מרע כל נכסיו, ואחר כך חזר בו במקצת ממתנה זו, האם \u0003הוי\u0004 \u0005[הינה\u0006 נחשבת\u0005]\u0006 \u0003חזרה ב\u0004כל המתנה \u0003כולה,\u0004 \u0003או לא,\u0004 וממה שלא חזר בו — לא חזר? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בברייתא \u0005:\u0006 נתן את נכסיו \u0003כולן לראשון ו\u0004אחר כך חזר בו \u0003ו\u0004נתן \u0003מקצתן לשני\u0004 — במקרה כזה ה\u0003שני קנה\u0004 את המקצת הזה, וה\u0003ראשון לא קנה.\u0004 ומציעים: \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר \u0003בשמת\u0004 המצווה, ומכאן נלמד שחזר בו לגמרי מן המתנה שנתן לראשון?","ודוחים: \u0003לא,\u0004 מדובר פה \u0003בשעמד\u0004 מחוליו, ולפיכך מתנתו לראשון בטלה, לפי שנתן לו כל נכסיו. ואילו מתנתו לשני, שהיתה רק במקצת — הרי זו מתנה. אבל אם היה מת, היה הראשון מקבל את מה שנותר, לפי שלא חזר בכל.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לומר, \u0003מדקתני סיפא\u0004 \u0005[מ\u0006מה \u0005ששנה\u0006 ב\u0005סוף\u0006 ברייתא זו\u0005]:\u0006 נתן \u0003מקצתן לראשון, ו\u0004אחר כך נתן \u0003כולן,\u0004 כל השאר, \u0003לשני\u0004 — במקרה כזה \u0003ראשון קנה, שני לא קנה.\u0004 ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שהברייתא מדברת \u0003בשעמד, משום הכי\u0004 \u0005[כך]\u0006 \u0003שני לא קנה,\u0004 לפי שנתן לו את כל נכסיו ועמד מחוליו. \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 שמדובר \u0003בשמת,\u0004 אם כן \u0003תרוייהו ליקנו\u0004 \u0005[ששניהם יקנו]\u0006 כל אחד את מה שניתן לו!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יימר לרב אשי: ותהוי נמי\u0004 \u0005[ושתהיה גם כן]\u0006 ההלכה שבתחילת הברייתא \u0003בשעמד,\u0004 ומכל מקום יש להוכיח מכאן שחזרה במקצת הריהי חזרה בכל. שכן \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 כי \u0003חזרה במקצת הויא\u0004 \u0005[נחשבת]\u0006 \u0003חזרה בכולה\u0004 \u0005[בכל],\u0006 \u0003היינו\u0004 \u0005[זהו\u0006 הטעם\u0005]\u0006 שה\u0003שני מיהת\u0004 \u0005[על כל פנים]\u0006 \u0003קנה,\u0004 שהרי נותרו הנכסים ששייר השכיב מרע לעצמו. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 ש\u0003חזרה במקצת לא הויא\u0004 \u0005[אינה נחשבת]\u0006 \u0003חזרה בכולה,\u0004 ומה שלא נתן לשני נותר ביד הראשון — אם כן \u0003ניהוי\u0004 \u0005[יהיה]\u0006 \u0003כמחלק\u0004 נכסיו כולם בזה אחר זה, \u0003ולחד מינייהו\u0004 \u0005[ולאחד מהם]\u0006 \u0003לא ליקנו\u0004 \u0005[ייקנו]\u0006 הנכסים, שהרי חילק הכל, וכשעמד — בטלה החלוקה!","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003חזרה במקצת הויא\u0004 \u0005[הריהי]\u0006 \u0003חזרה בכולה; רישא\u0004 \u0005[בתחילה],\u0006 בהלכה הראשונה שבברייתא, כשנתן כולן לראשון ומקצתן לשני — \u0003משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 שראשון לא קנה והשני קנה \u0003בין שמת, בין שעמד\u0004 מחוליו. \u0003סיפא\u0004 \u0005[\u0006ב\u0005סופה],\u0006 כשנתן מקצתן לראשון והשאר לשני — \u0003לא משכחת לה\u0004 \u0005[אינך מוצא אותה]\u0006 שראשון קנה ושני לא קנה, \u0003אלא כשעמד,\u0004 אבל אם מת — שניהם קונים.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 אם \u0003הקדיש כל נכסיו ועמד\u0004 מחוליו, \u0003מהו\u0004 הדין בכגון זה? \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי \u0003כל\u0004 דבר הנוגע \u0003לגבי הקדש גמר ומקני\u0004 \u0005[גומר בליבו ומקנה]\u0006 בלא תנאי, ואף אם עמד מחוליו ההקדש עומד בעינו\u0005,\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כל\u0004 דבר הנוגע \u0003לגבי נפשיה\u0004 \u0005[עצמו]\u0006 \u0003לא גמר ומקני\u0004 \u0005[אינו גומר בליבו ומקנה]?\u0006","ויש עוד לשאול: אם \u0003הפקיר כל נכסיו, מהו? מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי \u0003כיון\u0004 שהפקר הוא \u0003אף לעניים\u0004 \u0003כעשירים,\u0004 יש לומר שבמקרה זה \u0003גמר ומקני\u0004 \u0005[גומר\u0006 בליבו \u0005ומקנה]\u0006 משום המצוה שבדבר, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כל\u0004 דבר הנוגע \u0003לגבי נפשיה\u0004 \u0005[עצמו]\u0006 \u0003לא גמר ומקני\u0004 \u0005[אינו גומר ומקנה]?\u0006","ועוד שאלה: אם \u0003חילק כל נכסיו לעניים, מאי\u0004 \u0005[מה]\u0006 יהא הדין? \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי \u0003צדקה ודאי מגמר גמר ומקני\u0004 \u0005[גומר בליבו ומקנה],\u0006 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כל\u0004 דבר הנוגע \u0003לגבי נפשיה\u0004 \u0005[עצמו]\u0006 \u0003לא גמר ומקני\u0004 \u0005[אינו גומר ומקנה]?\u0006 לכל אחת מן השאלות הללו לא נמצאה תשובה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת\u0006 היתה בענין זה\u0005]:\u0006 אם \u0003הקדיש כל נכסיו, מהו?\u0004 או אם \u0003הפקיר כל נכסיו, מהו?\u0004 וכן אם \u0003חילק כל נכסיו לעניים, מהו?\u0004 אף לשאלות הללו לא נמצאה תשובה ועל כן אף הן \u0003תיקו\u0004 \u0005[תעמודנה]\u0006 במקומן.","\u0003אמר רב ששת:\u0004 לשון \u0003\"יטול\" ו\"יזכה\" ו\"יחזיק\" ו\"יקנה\"\u0004 — \u0003כולן לשון מתנה הן. במתניתא תנא\u0004 \u0005[בברייתא שנה]:\u0006 \u0003אף \"יחסין\"\u0004 (יחזיק, יקנה בירושה) \u0003ו\"ירת\"\u0004 (ירש) כאשר מדובר \u0003בראוי ליורשו, ו\u0004שיטת \u0003ר' יוחנן בן ברוקא היא,\u0004 שיכול להוריש את כל נכסיו לכל מי שירצה מבניו, בלשון ירושה (ולא רק בלשון מתנה).","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו:"],["אם אמר בלשון \u0003\"יהנה בהן\", מהי\u0004 ההלכה? האם כוונתו \u0003דניהוי כולהו\u0004 \u0005[שיהיו כולם]\u0006 \u0003מתנה קאמר\u0004 \u0005[הוא אומר],\u0006 \u0003או דלמא ליתהני מינייהו מידי קאמר\u0004 \u0005[שמא שייהנה מהם משהו הוא אומר]?\u0006 וכן אם אמר לשון \u0003\"יראה בהן\", מהו?\u0004 או לשון \u0003\"יעמוד בהן\", מהו?\u0004 או לשון \u0003\"ישען בהן\", מהו?\u0004 לאף אחת מן השאלות הללו לא נמצאה תשובה, ולכן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","במשנתנו דובר על מתנת שכיב מרע בכל נכסיו שאם עמד חוזר ממנה. \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 שכיב מרע ש\u0003מכר כל נכסיו, מהו\u0004 הדין בכגון זה? \u0003אמר רב יהודה אמר רב: אם עמד\u0004 והבריא מחוליו \u0003אינו חוזר\u0004 במכר זה. \u0003וזימנין\u0004 \u0005[ופעמים]\u0006 ש\u0003אמר רב יהודה אמר רב: אם עמד חוזר.\u0004 ומעירים: \u0003ולא פליגי\u0004 \u0005[ואין\u0006 הדברים \u0005חלוקים]:\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר שהרי זה חוזר בו, מדובר באופן \u0003דאיתנהו לזוזי בעינייהו\u0004 \u0005[שנמצאים הכספים בעינם],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שאמר שאינו חוזר בו — \u0003דפרעינהו\u0004 \u0005[שפרע אותם]\u0006 \u0003בחובו,\u0004 שיש לומר שלשם כך מכר — כדי שיוכל לפרוע את חובו.","ועוד \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003שכיב מרע שהודה\u0004 שהוא חייב ממון לאדם מסויים (גם אם אינו חייב לו באמת), \u0003מהו\u0004 הדין? היש בכך ממש, והאם יש לה דין של מתנת שכיב מרע? ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממעשה שהיה, ש\u0003איסור גיורא\u0004 \u0005[הגר]\u0006 אביו של רב מרי \u0003הוה ליה תריסר אלפי זוזי בי\u0004 \u0005[היו לו שנים עשר אלף זוזים בבית]\u0006 \u0003רבא. רב מרי בריה\u0004 \u0005[בנו]\u0006 של איסור, \u0003הורתו\u0004 היתה \u0003שלא בקדושה,\u0004 שאמו הרתה אותו לאיסור קודם שנתגייר, \u0003ולידתו בקדושה הואי\u0004 \u0005[היתה]\u0006 לאחר שהתגייר איסור אביו, \u0003ובי רב הוה\u0004 \u0005[ובבית המדרש היה]\u0006 ולא באותו מקום.","כאשר היה איסור חולה \u0003אמר רבא,\u0004 שהכסף היה מופקד אצלו, וסבור היה שיזכה בו \u0003: היכי ניקנינהו\u0004 \u0005[איך יקנה]\u0006 \u0003רב מרי להני זוזי\u0004 \u0005[את הכספים הללו]?\u0006 ובוחן היה את האפשרויות השונות: \u0003אי\u0004 \u0005[אם]\u0006 \u0003בירושה\u0004 — \u0003לאו בר\u0004 \u0005[לא בן]\u0006 \u0003ירושה הוא,\u0004 שכיון שלא היתה הורתו בקדושה אינו נחשב כבנו, אלא כגר שנתגייר לבדו, שאין לו קשר משפחתי עם אביו; \u0003אי\u0004 \u0005[אם]\u0006 \u0003במתנה\u0004 יתן לו, כשכיב מרע — הלא \u0003מתנת שכיב מרע כירושה שויוה רבנן\u0004 \u0005[עשו אותה חכמים],\u0006 ולפיכך \u0003כל היכא דאיתיה\u0004 \u0005[מקום שישנו]\u0006 \u0003בירושה\u0004 — \u0003איתיה\u0004 \u0005[ישנו]\u0006 \u0003במתנה, כל היכא דליתיה\u0004 \u0005[מקום שאינו]\u0006 \u0003בירושה\u0004 — \u0003ליתיה\u0004 \u0005[אינו]\u0006 גם \u0003במתנה.\u0004","\u0003אי\u0004 \u0005[אם]\u0006 לקנות את הכספים הללו \u0003ב\u0004קנין \u0003משיכה\u0004 — הלא \u0003ליתנהו גביה\u0004 \u0005[אינם בידו]\u0006 של רב מרי, שיוכל לקנותם. \u0003אי\u0004 \u0005[אם]\u0006 תאמר שיקנה אותם איסור לרב מרי \u0003ב\u0004קנין \u0003חליפין,\u0004 שיגביה איסור חפץ כלשהו, ועל ידי כך יקנה לרב מרי את הכספים — הלא \u0003אין מטבע נקנה בחליפין. אי\u0004 \u0005[אם]\u0006 תאמר שיקנה לו את הכספים הללו בקנין \u0003אגב קרקע\u0004 — \u0003לית ליה ארעא\u0004 \u0005[אין לו\u0006 לאיסור \u0005קרקע].\u0006 והוסיף רבא (שהמעות היו מופקדות אצלו): \u0003אי\u0004 \u0005[אם]\u0006 תאמר שיקנה אותם לרב מרי \u0003במעמד שלשתן\u0004 שיצווה עלי בפני רב מרי לתת לו את הכסף, ודי בכך להקנות לו — \u0003אי שלח\u0004 \u0005[אם ישלח]\u0006 \u0003לי\u0004 לבוא אליו \u0003לא אזילנא\u0004 \u0005[אבוא].\u0006 ונמצא שלאחר מותו יישאר הכסף בידי.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב איקא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אמי: אמאי\u0004 \u0005[מדוע]\u0006 סבור אתה שאין לו דרך להקנותו לרב מרי? \u0003ולודי\u0004 \u0005[ושיודה]\u0006 \u0003איסור דהלין זוזי\u0004 \u0005[שזוזים,\u0006 כספים \u0005אלה]\u0006 של \u0003רב מרי נינהו\u0004 \u0005[הם],\u0006 \u0003וליקנינהו\u0004 \u0005[ויקנה אותם]\u0006 לרב מרי \u0003באודיתא\u0004 \u0005[בהודאה]!\u0006 \u0003אדהכי\u0004 \u0005[בינתיים]\u0006 עד שהיו דנים בנושא זה, \u0003נפק אודיתא מבי\u0004 \u0005[יצאה הודאה מביתו]\u0006 של \u0003איסור\u0004 הגר, שהכסף שייך לרב מרי. \u0003איקפד\u0004 \u0005[הקפיד]\u0006 \u0003רבא\u0004 על כך, \u0003אמר: קא מגמרי טענתא לאינשי ומפסדי לי\u0004 \u0005[מלמדים הם טענות לאנשים וגורמים לי הפסד].\u0006 ועל כל פנים, מכאן ראיה שהודאת שכיב מרע יפה כוחה להקנות למקבל."],["שנינו במשנה שאם \u0003שייר\u0004 השכיב מרע \u0003קרקע כל שהוא\u0004 — \u0003מתנתו קיימת\u0004 גם אם עמד מחוליו. ושואלים: \u0003וכמה\u0004 הוא שיעור של \u0003\"כל שהוא\"? אמר רב יהודה אמר רב: קרקע כדי פרנסתו,\u0004 שאז מוכח שרצה לתת את הנכסים בכל מקרה, גם אם יחיה, שהרי השאיר לעצמו לצורך חייו. \u0003ורב ירמיה בר אבא אמר:\u0004 אפילו שייר \u0003מטלטלין כדי פרנסתו\u0004 גם כן מתנתו קיימת.","\u0003אמר רבי זירא: כמה מכוונן\u0004 \u0005[מכוונות]\u0006 מתאימות זו לזו ונאות \u0003שמעתתא דסבי\u0004 [\u0005ההלכות של הזקנים],\u0006 רב יהודה ורב ירמיה בר אבא. שכן שייר \u0003קרקע טעמא מאי\u0004 \u0005[מה הטעם]\u0006 צריך שיהיה בה כדי פרנסתו? \u0003דאי קאי סמיך עליה\u0004 \u0005[שאם\u0006 הוא \u0005עומד\u0006 מחוליו הריהו \u0005סומך\u0006 \u0005עליה],\u0006 \u0003מטלטלי נמי אי קאי סמיך עילויהו\u0004 \u0005[מיטלטלים גם כן, אם\u0006 הוא \u0005יעמוד\u0006 מחוליו הריהו \u0005סומך עליהם].\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף: ומאי כוונתא\u0004 \u0005[ומה מכוון\u0006 בהן\u0005]\u0006 באותן שמועות? הלא \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שייר \u0003מטלטלין,\u0004 יש להקשות עליו: הרי \u0003\"קרקע\" תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]!\u0006 \u0003מאן דאמר\u0004 \u0005[מי שאומר]:\u0006 קרקע \u0003כדי פרנסתו,\u0004 הלא \u0003\"כל שהוא\" תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003וכל היכא דתני\u0004 \u0005[מקום ששונה]\u0006 \u0003\"קרקע\",\u0004 כוונת הדברים היא \u0003קרקע דוקא? והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכותב כל נכסיו\u0004 כמתנה \u0003לעבדו\u0004 הכנעני — \u0003יצא\u0004 העבד \u0003בן חורין,\u0004 שהרי הוא בכלל הנכסים. אבל אם \u0003שייר קרקע כל שהוא\u0004 מנכסיו, שלא כתב לו — \u0003לא יצא\u0004 העבד \u0003בן חורין,\u0004 משום שאנו אומרים שהשיור בקרקע כולל שיור גם בעבד עצמו. \u0003ר' שמעון אומר: לעולם\u0004 בכל מקרה \u0003הוא בן חורין, עד שיאמר \"כל נכסי נתונין לפלוני עבדי חוץ מאחר מרבוא שבהן\".\u0004 שכיוון שלא פירש מה משייר — שמא כוונתו לעבד, שאת העבד עצמו לא שיחרר, ונמצא שאין כאן נתינה כלל."],["\u0003ו\u0004כהמשך לדברים אלו \u0003אמר רב דימי בר יוסף אמר ר' אלעזר: עשו\u0004 חכמים \u0003מטלטלין שיור אצל עבד,\u0004 כלומר, לא רק אם שייר האדון קרקע, אלא אפילו אם שייר מיטלטלין כלשהם — הרי הם שיור, ולא יצא העבד לחירות, שאף הוא בכללם. \u0003ו\u0004אולם \u0003לא עשו מטלטלין שיור אצל כתובה\u0004 שהכותב נכסיו לבניו וכותב לאשתו קרקע כלשהו — איבדה כתובתה, אבל אם נתן לה מיטלטלים — לא איבדה כתובתה. ומכל מקום, מהדין האמור בעבד עולה שקרקע השנויה במשנה היא לאו דווקא קרקע!","השיב רב יוסף: \u0003התם\u0004 \u0005[שם],\u0006 באותה משנה לגבי עבד, \u0003בדין הוא\u0004 ש\u0003לא ליתני\u0004 \u0005[ישנה]\u0006 \u0003קרקע\u0004 כלל, אלא \u0003איידי דתנא רישא\u0004 \u0005[מתוך ששנה בתחילה]\u0006 לפני אותה משנה, הלכות הנוגעות לקרקע, \u0003ר' עקיבא אומר: קרקע כל שהוא חייבת בפאה ובבכורים, ו\u0004ראויה \u0003לכתוב עליהם\u0004 על קרקע זו \u0003פרוזבול, ולקנות עמהם\u0004 אגב קרקעות \u0003נכסים שאין להם אחריות,\u0004 כלומר, מיטלטלים, כאשר הקרקע עצמה נקנית \u0003בכסף ובשטר ובחזקה,\u0004 שהם דרכי הקנין של קרקע, \u0003משום הכי קתני\u0004 \u0005[כך שנה]\u0006 גם בהמשך \u0003קרקע.\u0004","ועוד הקשה אביי על רב יוסף: \u0003ו\u0004כי \u0003כל היכא דתני\u0004 \u0005[מקום ששנה]\u0006 \u0003\"כל שהוא\" לית ליה שיעורא\u0004 \u0005[אין לו שיעור]\u0006 כלל, עד שתמהת על דברי רב יהודה, שפירש את משנתנו בכדי פרנסתו? \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' דוסא בן הרכינס אומר: חמש רחלות\u0004 ש\u0003גוזזות\u0004 כל אחת מהן \u0003מנה מנה ופרס\u0004 (וחצי) — \u0003חייבות בראשית הגז\u0004 לתיתו לכהן\u0003,\u0004 אבל אם היו גוזזות פחות אין מפרישים ראשית הגז. \u0003וחכמים אומרים: חמש רחלות גוזזות כל שהן\u0004 חייבות בכך. \u0003ואמרינן\u0004 \u0005[ואומרים היינו]:\u0006 \u0003וכמה\u0004 הוא שיעורו של \u0003\"כל שהן\"\u0004 האמור בדברי חכמים\u0003? אמר רב: מנה ופרס\u0004 בסך הכל, \u0003ובלבד שיהו מחומשות,\u0004 כלומר, שלכל אחת מהן תהא חמישית מכמות זו. משמע ש\"כל שהוא\" יש לו שיעור מסויים!","השיב לו רב יוסף: \u0003התם\u0004 \u0005[שם]\u0006 \u0003בדין הוא\u0004 ש\u0003לא ליתני\u0004 \u0005[ישנה]\u0006 לשון \u0003\"כל שהוא\", ואיידי דקאמר\u0004 \u0005[ומתוך שאמר]\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון,\u0006 ר' דוסא בן הרכינס\u0005]\u0006 \u0003שיעורא רבה\u0004 \u0005[שיעור גדול]\u0006 \u0003אמר איהו נמי\u0004 \u0005[הוא גם כן]\u0006 \u0003שיעורא זוטרא\u0004 \u0005[שיעור קטן],\u0006 לפיכך \u0003קרי לה\u0004 \u0005[קורא לו]\u0006 \u0003\"כל שהוא\".\u0004 אבל במשנתנו יש לומר כי \"כל שהוא\" — דווקא הוא.","ובענין דינו של עבד, כקרקע או כמיטלטלין, מקדימים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 לנו\u0005],\u0006 שאם \u0003אמר \"מטלטלי לפלניא\"\u0004 \u0005[לפלוני]\u0006 — \u0003כל מאני תשמישתיה קני\u0004 \u0005[כלי תשמישו קנה],\u0006 \u0003לבר מחטי ושערי\u0004 \u0005[חוץ מחיטים ושעורים]\u0006 שאינם נקראים \"מיטלטלים\" סתם. אם אמר \u0003\"כל מטלטלי לפלניא\"\u0004 \u0005[לפלוני]\u0006 — \u0003אפילו חטי ושערי\u0004 \u0005[חיטים ושעורים]\u0006 קנה, \u0003ואפילו\u0004 אבן \u0003ריחים העליונה\u0004 שהיא מיטלטלת לפעמים \u0003קנה,\u0004 אף על פי שאין רגילים לטלטלה, \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מריחים התחתונה,\u0004 שהיא קבועה בקרקע ואין מטלטלים אותה כלל, ואותה לא קנה. אם אמר \u0003\"כל\u0004 ה\u0003מטלטל\u0004 נתון לפלוני \u0003\"\u0004— \u0003אפילו\u0004 אבן \u0003ריחים התחתונה קני\u0004 \u0005[קונה],\u0006 לפי שהיא ניתנת לטילטול.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 שאלה ללומדים\u0005]\u0006 על סמך הדברים הללו: \u0003עבדא כמקרקעא\u0004 \u0005[עבד כקרקעות]\u0006 \u0003או כמטלטלא דמי\u0004 \u0005[כמיטלטלים נחשב]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אויא לרב אשי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר, ממה ששנינו: \u0003המוכר את העיר\u0004 — \u0003מכר בתים, שיחין ומערות, ומרחצאות, ובית הבדין, ובית השלחין\u0004 (שדות מושקים בידי אדם), \u0003אבל לא\u0004 מכר \u0003את המטלטלין. ובזמן שאמר: \"היא וכל מה שבתוכה\", אפילו היו בה בהמה או עבדים\u0004 — \u0003הרי כולן מכורין.\u0004 ומעתה, \u0003אי אמרת בשלמא כמטלטלא דמי\u0004 \u0005[נניח אם אתה אומר\u0006 שהעבד \u0005כמיטלטלים\u0006 הוא \u0005נחשב],\u0006 \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003לא מיזדבן ברישא\u0004 \u0005[אינו נמכר\u0006 \u0005ב\u0006מקרה \u0005הראשון],\u0006 \u0003אלא אי אמרת כמקרקעא דמי\u0004 \u0005[אם אומר אתה\u0006 ש\u0005כקרקע\u0006 הוא \u0005נחשב],\u0006 \u0003אמאי לא מיזדבן\u0004 \u0005[מדוע אינו נמכר]\u0006 יחד עם שאר נכסי המקרקעין\u0005?\u0006","ענה לו רב אשי: \u0003ואלא מאי\u0004 \u0005[מה]\u0006 אתה אומר? \u0003כמטלטלא דמי\u0004 \u0005[כמיטלטלים\u0006 הוא \u0005נחשב]?\u0006 אם כן \u0003מאי\u0004 \u0005[מהו]\u0006 לשון \u0003\"אפילו\"\u0004 האמורה בעבדים, לומר שגם הם בכלל \"כל מה שבתוכה\"? והרי גם הם בכלל המיטלטלים! \u0003אלא מאי אית\u0004 \u0005[מה יש]\u0006 \u0003לך למימר\u0004 \u0005[לומר]\u0006 כדי להסביר לשון זו? \u0003שאני מטלטלא דנייד ממטלטלא דלא נייד\u0004 \u0005[שונה מיטלטל שנייד ממיטלטל שאינו נייד],\u0006 ולפיכך היה מקום לומר שעבדים ובהמה אינם בכלל שאר מיטלטלים הנמכרים עם העיר. אם כן, מאותו טעם עצמו, \u0003אפילו תימא כמקרקעא דמי\u0004 \u0005[תאמר\u0006 שעבד \u0005כקרקע\u0006 הוא \u0005נחשב],\u0006 \u0003שאני מקרקעא דנייד ממקרקעא דלא נייד\u0004 \u0005[שונה קרקע ניידת מקרקע שאינה ניידת].\u0006 ואין איפוא הוכחה ממשנה זו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לבעיה זו מן האמור לעיל, ששנינו: \u0003הכותב לעבדו כל נכסיו\u0004 — \u0003יצא\u0004 העבד \u0003בן חורין,\u0004 אם \u0003שייר קרקע כל שהוא\u0004 שלא נתן לו — \u0003לא יצא בן חורין. ר' שמעון אומר: לעולם הוא בן חורין\u0004 — \u0003עד שיאמר \"כל נכסי נתונין לפלוני עבדי, חוץ מאחד מרבוא שבהן\".\u0004","\u0003ואמר רב דימי בר יוסף אמר ר' אלעזר: עשו מטלטלין שיור אצל עבד, ולא עשו מטלטלין שיור אצל כתובה. ואמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]\u0006 שתיקנו כך? והסביר רב נחמן: \u0003עבדא מטלטלא\u0004 \u0005[עבד מיטלטל]\u0006 \u0003הוא, ומטלטלא למטלטלא הוי\u0004 \u0005[ומיטלטל למיטלטל הריהו]\u0006 \u0003שיור, ו\u0004אילו \u0003כתובת אשה מקרקעא\u0004 \u0005[\u0006נכס של \u0005קרקע]\u0006 \u0003הוא,\u0004 שהרי היא גובה את כתובתה מן הקרקעות, \u0003ומטלטלא למקרקעא לא הוי\u0004 \u0005[ו\u0006דבר שהוא \u0005מיטלטל, לקרקע אינו]\u0006 נחשב \u0003שיור.\u0004 ואם כן מכאן יש ללמוד לשאלתנו, שעבד נחשב כמיטלטל!"],["\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אשי: \u0003אנן\u0004 \u0005[אנו]\u0006 לא מטעם שיור אנו דנים בהלכה זו, אלא \u0003משום דלאו כרות גיטא מתנינן לה\u0004 \u0005[שאין\u0006 זו \u0005כריתות גט אנו שונים אותה].\u0006 כלומר, הטעם מדוע בשיור כזה אין העבד משתחרר, אינו משום שעבד נחשב חלק מן הנכסים, אלא משום שהגט באופן זה אינו מנתק לגמרי את הקשר ביניהם, ומשום כך לא חל השחרור.","\u0003אמר רבא אמר רב נחמן: חמשה\u0004 — אין דנים בהם את ההלכות המיוחדות להם \u0003עד שיכתבו כל נכסיהם\u0004 ולא ישיירו, \u0003ואלו הן: שכיב מרע, עבדו, אשתו, ובניו,\u0004 ו\u0003מברחת.\u0004","ומבארים: \u0003שכיב מרע, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003שכיב מרע שכתב כל נכסיו לאחרים ושייר קרקע כל שהוא,\u0004 אם עמד מחוליו — \u0003מתנתו קיימת, לא שייר קרקע כל שהוא\u0004 — \u0003אין מתנתו קיימת.\u0004","\u0003עבדו, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכותב כל נכסיו לעבדו\u0004 — \u0003יצא בן חורין, שייר קרקע כל שהוא\u0004 — \u0003לא יצא בן חורין.\u0004","\u0003אשתו\u0004 מהו? ש\u0003אמר רב יהודה אמר שמואל: הכותב כל נכסיו לאשתו\u0004 — \u0003לא עשאה אלא אפטרופא\u0004 \u0005[אפוטרופסית]\u0006 לנכסים, ולא התכוון להקנות לה אותם באמת. ודבר זה הוא דווקא כשכותב לה את כל הנכסים בלי שיור.","\u0003בניו, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכותב כל נכסיו לבניו, וכתב לאשתו קרקע כל שהוא\u0004 — \u0003אבדה כתובתה,\u0004 אבל אם לא כתב להם כל נכסיו — לא איבדה כתובתה.","ו\u0003מברחת\u0004 נכסיה מבעלה, כלומר, אשה שעומדת להינשא ואינה רוצה שרכושה יעבור לבעלה, הריהי כותבת שטר בו היא מעבירה את נכסיה לאחרים, ובמקרה זה אם תתגרש או תתאלמן מבעלה אמרו חכמים שיחזרו אליה הנכסים. ועל שטר כזה \u0003אמר מר: מברחת צריכה שתכתוב כל נכסיה,\u0004 אבל אם משיירת לעצמה דבר מנכסיה, שאינה מקנה אותו בשטר זה — אינה יכולה לתבוע את הנכסים לכשתתאלמן או תתגרש.","ומעירים: \u0003ובכולהו\u0004 \u0005[ובכל]\u0006 הדברים הללו גם \u0003מטלטלי הוי\u0004 \u0005[מיטלטלים הריהם\u0006 נחשבים\u0005]\u0006 \u0003שיור, לבר\u0004 \u0005[חוץ]\u0006 \u0003מכתובה,\u0004 שהכותב לאשתו קרקע עם בניו, אם לא שייר קרקע אלא מיטלטלים — איבדה כתובתה, שהרי לא נותר לה ממה לגבות, לפי \u0003דאמקרקעי\u0004 \u0003תקינו רבנן\u0004 \u0005[שעל קרקעות תיקנו חכמים]\u0006 את הכתובה, ואולם \u0003ממטלטלי\u0004 \u0005[ממיטלטלים]\u0006 \u0003לא תקון רבנן\u0004 \u0005[תיקנו חכמים].\u0006","\u0003אמימר אמר: מטלטלי דכתיבי\u0004 \u0005[מיטלטלים שכתובים\u0006 ומפורשים\u0005]\u0006 \u0003בכתובה\u0004 שתגבה מהם את החוב, \u0003ואיתנהו בעינייהו\u0004 \u0005[ו\u0006הם \u0005נמצאים בעינם]\u0006 — \u0003הוי\u0004 \u0005[הריהם]\u0006 \u0003שיור\u0004 ולא איבדה כתובתה.","ועוד לענין לשונות של מתנה, אם \u0003אמר \"נכסי לפלניא\"\u0004 \u0005[לפלוני]\u0006 — \u0003עבדא איקרי\u0004 \u0003\"נכסי\"\u0004 \u0005[העבד נקרא \"נכסים\"],\u0006 והוא בכלל זה. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכותב כל נכסיו לעבדו\u0004 — \u0003יצא בן חורין,\u0004 משמע שגם העבד הריהו כלול בנכסים. \u0003ארעא איקרי\u0004 \u0003\"נכסי\"\u0004 \u0005[הקרקע נקראת \"נכסים\"],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003נכסים שיש להן אחריות\u0004 (כלומר, קרקעות) \u0003נקנין בכסף ובשטר ובחזקה,\u0004 הרי שקרקע קרויה \"נכסים\". \u0003גלימא\u0004 \u0005[גלימה]\u0006 וכל שאר בגדים ומיטלטלים \u0003איקרי \"נכסי\"\u0004 \u0005[נקראת \"נכסים\"],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 באותה משנה\u0005]:\u0006 \u0003ו\u0004נכסים \u0003שאין להן אחריות\u0004 (מיטלטלין) — \u0003אין נקנין אלא ב\u0004קנין \u0003משיכה,\u0004 משמע שהם נקראים נכסים.","\u0003זוזי איקרי \"נכסי\"\u0004 \u0005[כספים נקראים \"נכסים\"],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 באותה משנה\u0005]:\u0006 \u0003ו\u0004נכסים \u0003שאין להן אחריות נקנין עם נכסים שיש להן אחריות,\u0004 כשאותם נכסים נקנים \u0003בכסף ובשטר ובחזקה,\u0004 ובכלל זה גם כסף. ומביאים ראיה לדבר: \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב פפא הוו ליה תריסר אלפי זוזי\u0004 \u0005[היו לו שנים עשר אלפי זוזים]\u0006 בהלוואה שהלווה לאנשי \u0003בי חוזאי, אקנינהו ניהליה\u0004 \u0005[הקנה אותם]\u0006 \u0003לרב שמואל בר אחא\u0004 שנסע לבי חוזאי \u0003אגב אסיפא דביתיה\u0004 \u0005[סף ביתו],\u0006 כדי שיוכל רב שמואל בר אחא לגבות את הכספים, ולכתוב להם שובר על פרעון חובם. \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 רב שמואל בר אחא והכסף בידו, שמח רב פפא כל כך עד ש\u0003נפק לאפיה\u0004 \u0005[יצא לקראתו]\u0006 \u0003עד\u0004 המקום \u0003תווך.\u0004 הרי שהמעות נקנות אגב קרקע.","\u0003שטרא איקרי \"נכסי\"\u0004 \u0005[שטר\u0006 גם כן \u0005נקרא \"נכסים\"],\u0006 כפי ש\u0003אמר רבה בר יצחק: שני\u0004 סוגי \u0003שטרות הן\u0004 בהעברת קרקע: אם \u0003אמר\u0004 לעדים \u0003\"זכו\u0004 (בקנין סודר) \u0003בשדה זה לפלוני, וכתבו לו את השטר\"\u0004 — \u0003חוזר בשטר\u0004 שיכול להתחרט על מה שאמר שיכתבו לו שטר, אבל \u0003אינו חוזר בשדה\u0004 אם כבר זכו לו. אבל אם אמר \"זכו בשדה זה \u0003על מנת שתכתבו לו את השטר\"\u0004 — \u0003חוזר בין בשטר בין בשדה,\u0004 שהרי התנה את הזכייה בשדה בכתיבת השטר, ואם חוזר בו מן השטר — חוזר בכל.","\u0003ורב חייא בר אבין אמר\u0004 בשם \u0003רב הונא: שלשה שטרות הן, תרי\u0004 \u0005[שנים]\u0006 — \u0003הני דאמרן\u0004 \u0005[אלה שאמרנו],\u0006 \u0003אידך\u0004 \u0005[\u0006מין \u0005אחר]\u0006 של שטר הוא — \u0003אם קדם מוכר וכתב את השטר\u0004 והמתין עד שיבוא הלוקח וישלם לו, ואז יתן לו את השטר, \u0003כאותה ששנינו:\u0004"],["\u0003כותבין שטר\u0004 מכר \u0003למוכר ואף על פי שאין לוקח\u0004 (קונה) \u0003עמו,\u0004 כי השטר אינו מחייב אלא את המוכר בלבד. ובמקרה זה, כשנכתב השטר, \u0003כיון שהחזיק זה\u0004 הקונה \u0003בקרקע\u0004 — \u0003נקנה\u0004 ה\u0003שטר\u0004 ב\u0003כל מקום שהוא. וזו היא ששנינו: נכסים שאין להן אחריות\u0004 (ובכלל זה, השטר) \u0003נקנין עם הנכסים שיש להן אחריות,\u0004 כשאלו נקנים \u0003ב\u0004קנין \u0003כסף ובשטר ובחזקה.\u0004 ומכאן אנו לומדים שהשטר נקרא \"נכסים\".","\u0003בהמה איקרי \"נכסי\"\u0004 \u0005[נקראת \"נכסים\"],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003המקדיש נכסיו והיתה בהן בהמה ראויה לגבי מזבח, זכרים\u0004 שהיו בנכסיו — יהיו ל\u0003עולות, ונקבות\u0004 — \u0003ימכרו לצרכי זבחי שלמים.\u0004 הרי שאף בהמה בכלל נכסים. \u0003עופות איקרי \"נכסי\"\u0004 \u0005[נקראו \"נכסים\"],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003המקדיש נכסיו והיו בהן דברים הראויין לגבי מזבח, יינות, שמנים ועופות\u0004 וכו'.","הרי שעופות בכלל \"נכסים\". \u0003תפלין איקרי \"נכסי\"\u0004 \u0005[נקראו \"נכסים\"],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003המקדיש נכסיו\u0004 — \u0003מעלין\u0004 (מחשבים) \u0003לו\u0004 גם \u0003תפלין\u0004 שלו. הרי שתפילין הם בכלל הנכסים. עד כאן רשימת הדברים שפשוט היה שהם קרויים \"נכסים\". ואולם \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003ספר תורה מאי\u0004 \u0005[מה]\u0006 דינו? האם הוא בכלל נכסים או לא? והצדדים בשאלה: \u0003כיון\u0004 שהוא \u0003לא מזדבן\u0004 \u0005[נמכר],\u0006 שהרי \u0003אסור לזבוניה\u0004 \u0005[למכור אותו]\u0006 — \u0003לאו\u0004 \u0005[לא]\u0006 בכלל \u0003\"נכסי\"\u0004 \u0005[\"נכסים\"]\u0006 \u0003הוא.\u0004 \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003כיון דמזדבן\u0004 \u0005[ש\u0006הוא \u0005נמכר]\u0006 לצרכים מסויימים, כגון \u0003ללמוד תורה ולישא אשה\u0004 — בכלל \u0003\"נכסי\"\u0004 \u0005[\"נכסים\"]\u0006 \u0003הוא?\u0004 שאלה זו לא נפתרה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 במקומה.","\u0003סימן\u0004 למעשים הבאים: \u0003זוטרא אימיה דעמרם מתרתי אחוותא רב טובי ורב דימי ורב יוסף.\u0004","בענין אשה מברחת שהוזכר לעיל, מסופר: \u0003אימיה\u0004 \u0005[אימו]\u0006 של \u0003רב זוטרא בר טוביא כתבינהו לנכסה\u0004 \u0005[כתבה את\u0006 כל \u0005נכסיה]\u0006 \u0003לרב זוטרא בר טוביא\u0004 בנה, והסבירה שהיא עושה זאת משום \u0003דבעיא לאנסובי ליה\u0004 \u0005[שרצתה להינשא לו]\u0006 \u0003לרב זביד,\u0004 ולא רצתה שנכסיו יעברו אליו. \u0003אינסיבא\u0004 \u0005[נישאה]\u0006 לרב זביד \u0003ו\u0004אחר כך \u0003גרשה\u0004\u0005,\u0006 \u0003אתיא לקמיה\u0004 \u0005[באה לפני]\u0006 \u0003רב ביבי בר אביי\u0004 לתבוע את נכסיה מבנה, \u0003אמר\u0004 רב ביבי: הרי את הנכסים העבירה \u0003משום אנסובי\u0004 \u0005[נישואין],\u0006 \u0003והא אינסיבא\u0004 \u0005[והרי נישאה],\u0006 וכיון שהתקיימה כוונתה, למרות שאחר כך התגרשה — הנכסים שניתנו ניתנו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: משום דאתו ממולאי אמריתו מילי מולייתא\u0004 \u0005[שבאתם מאנשים כרותים,\u0006 מבני עלי, \u0005אומרים אתם דברים כרותים]?\u0006 \u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ששטר \u0003מברחת קני\u0004 \u0005[קונה]\u0006 המקבל, ואינו מחזיר לה, \u0003הני מילי היכא\u0004 \u0005[דברים אלו\u0006 אמורים \u0005במקום]\u0006 ש\u0003לא גליא\u0004 \u0005[גילתה]\u0006 \u0003דעתה\u0004 משום מה היא נותנת את הנכסים, \u0003אבל הכא גליא\u0004 \u0005[כאן גילתה]\u0006 \u0003דעתה\u0004 ש\u0003משום אינסובי\u0004 \u0005[נישואין]\u0006 \u0003הוא, והא אינסיבא ואיגרשה\u0004 \u0005[והרי נישאה והתגרשה],\u0006 וכיון שאינה נשואה עוד — הנכסים שייכים לה.","ועוד בענין אשה שכתבה את נכסיה לבנה, מסופר: \u0003אימיה\u0004 \u0005[אימו]\u0006 של \u0003רמי בר חמא, באורתא כתבתינהו לנכסה\u0004 \u0005[בערב כתבה את נכסיה]\u0006 \u0003לרמי בר חמא, בצפרא כתבתינהו\u0004 \u0005[בבוקר כתבה אותם]\u0006 \u0003ל\u0004אחיו \u0003רב עוקבא בר חמא. אתא\u0004 \u0005[בא]\u0006 \u0003רמי בר חמא לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב ששת, אוקמיה בנכסי\u0004 \u0005[\u0006ו\u0005העמידו בנכסים],\u0006 שמתנתו קדמה. \u0003אזל\u0004 \u0005[הלך]\u0006 \u0003רב עוקבא בר חמא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן, אוקמיה בנכסי\u0004 \u0005[העמידו בנכסים].\u0006","\u0003אתא\u0004 \u0005[בא]\u0006 \u0003רב ששת לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן\u0004 לדון איתו בדבר זה, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי טעמא אוקמיה מר\u0004 \u0005[מה טעם העמידו אדוני]\u0006 \u0003לרב עוקבא בר חמא\u0004 בנכסים? \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום דהדרא\u0004 \u0005[שחזרה]\u0006 \u0003בה, והא שכיבא\u0004 \u0005[והרי מתה],\u0006 ומתנת שכיב מרע הריהי ככתובה ומסורה, ונמצא שהנכסים כבר ניקנו לרמי בר חמא! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן, \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל:\u0004 כל מתנת שכיב מרע \u0003שאילו עמד\u0004 מחוליו היה \u0003חוזר\u0004 בה, כגון שנתן את כל נכסיו, אף במקרה שלא עמד מחוליו \u0003חוזר\u0004 הוא \u0003במתנתו.\u0004","אמר לו רב ששת: \u0003אימור\u0004 \u0005[אמור]\u0006 ש\u0003אמר שמואל\u0004 שחוזר בו — אם מתחרט ורוצה להשאיר את הנכס \u0003לעצמו,\u0004 ואולם לחזור בו כדי לתת \u0003לאחר מי\u0004 \u0005[האם]\u0006 גם כן \u0003אמר? אמר ליה\u0004 \u0005[לו],\u0006 \u0003בפירוש אמר שמואל: בין לעצמו בין לאחר\u0004 יכול לחזור.","ועוד מסופר: \u0003אימיה\u0004 \u0005[אימו]\u0006 של \u0003רב עמרם חסידא\u0004 \u0005[החסיד]\u0006 \u0003הוה\u0004 \u0005[היה]\u0006 \u0003לה מלוגא דשטראי\u0004 \u0005[צרור שטרות],\u0006 \u0003כי קא שכבא\u0004 \u0005[כאשר מתה]\u0006 \u0003אמרה: ליהוי\u0004 \u0005[שיהיו]\u0006 \u0003לעמרם ברי\u0004 \u0005[בני].\u0006 \u0003אתי אחוה לקמיה\u0004 \u0005[באו אחיו לפני]\u0006 \u0003רב נחמן, אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא משך\u0004 את החבילה הזו, ולא עשה בה קנין! \u0003אמר להו\u0004 \u0005[להם]:\u0006 אין צורך בכך, \u0003דברי שכיב מרע ככתובין וכמסורין דמו\u0004 \u0005[נחשבים].\u0006","ועוד מסופר: \u0003אחתיה\u0004 \u0005[אחותו]\u0006 של \u0003רב טובי בר רב מתנה כתבתינהו לנכסה\u0004 \u0005[כתבה את נכסיה]\u0006 \u0003לרב טובי בר רב מתנה\u0004 אחיה \u0003בצפרא\u0004 \u0005[בבוקר].\u0006 \u0003לפניא אתא\u0004 \u0005[בערב בא]\u0006 אח אחר שלה \u0003רב אחדבוי בר רב מתנה בכה לה,\u0004 \u0003אמר לה, השתא אמרי\u0004 \u0005[עכשיו יאמרו\u0006 האנשים\u0005]:\u0006 \u0003מר צורבא מרבנן ומר לאו צורבא מרבנן\u0004 \u0005[זה,\u0006 רב טובי, \u0005תלמיד חכם, וזה,\u0006 אני, \u0005אינו תלמיד חכם],\u0006 שהרי נתת דווקא לו את הנכסים! \u0003כתבתינהו ניהליה\u0004 \u0005[כתבה לו\u0006 את הנכסים\u0005].\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 רב טובי \u0005לפני]\u0006 \u0003רב נחמן. אמר ליה\u0004 \u0005[לו],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: כל שאילו עמד חוזר,\u0004 אף \u0003חוזר במתנתו,\u0004 ואם כן הנכסים הם של רב אחדבוי.","ועוד מסופר, \u0003אחתיה\u0004 \u0005[אחותו]\u0006 של \u0003רב דימי בר יוסף הוה\u0004 \u0005[היתה]\u0006 \u0003לה פיסקתא דפרדיסא\u0004 \u0005[חלקה של פרדס],\u0006 \u0003כל אימת דהות חלשא הוה מקניא ליה ניהליה\u0004 \u0005[כל פעם שהיתה חולה\u0006 וסבורה היתה שהיא עומדת למות, \u0005היתה מקנה לו\u0006 את החלק שלה\u0005],\u0006"],["\u0003וכי קיימא הות הדרא\u0004 \u0005[וכאשר היתה עומדת\u0006 מחוליה \u0005היתה חוזרת]\u0006 \u0003בה\u0004 מן המתנה. \u0003זימנא חדא חלשא\u0004 \u0005[פעם אחת חלתה],\u0006 \u0003שלחה ליה\u0004 \u0005[לו]:\u0006 \u0003תא קני\u0004 \u0005[בוא\u0006 ו\u0005קנה],\u0006 \u0003שלח\u0004 לה: \u0003לא בעינא\u0004 \u0005[איני רוצה].\u0006 \u0003שלחה ליה\u0004 \u0005[לו]:\u0006 \u0003תא קני כל היכא דבעית\u0004 \u0005[בוא וקנה בכל אופן שאתה רוצה].\u0006 \u0003אזל שיירה וקנו מינה\u0004 \u0005[הלך\u0006 ו\u0005שייר בה\u0006 משהו בחלקה הזו, \u0005ועשו קנין עימה]\u0006 עם אחותו על המתנה\u0005.\u0006 \u0003כי קיימא הדרא\u0004 \u0005[כאשר עמדה\u0006 מחוליה \u0005חזרה]\u0006 \u0003בה.\u0004","\u0003אתאי לקמיה\u0004 \u0005[באה לפני]\u0006 \u0003רב נחמן. שלח ליה\u0004 \u0005[לו]\u0006 לרב דימי: \u0003תא\u0004 \u0005[בוא]\u0006 לדין. \u0003לא אתא\u0004 \u0005[בא].\u0006 \u0003אמר: מאי איתי\u0004 \u0005[מה\u0006 טעם \u0005אבוא]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003שיירה וקנו מינה\u0004 \u0005[ו\u0006גם עשו \u0005קנין עמה]\u0006 ולכן הכל שלי! \u0003שלח ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003אי\u0004 \u0003לא אתית\u0004 \u0005[תבוא],\u0006 \u0003מחינא לך בסילוא דלא מבע דמא\u0004 \u0005[אכה אותך בקוץ שאינו מוציא דם],\u0006 כלומר, אטיל עליך חרם.","וחקר רב נחמן בדבר, \u0003אמר להו לסהדי\u0004 \u0005[להם לעדים]:\u0006 \u0003היכי הוה\u0004 \u0005[כיצד היה]\u0006 \u0003מעשה\u0004 נתינה זו? \u0003אמרו ליה\u0004 \u0005[לו],\u0006 \u0003אמרה הכי\u0004 \u0005[כך]:\u0006 \u0003ווי דקא מיתה הך איתתא\u0004 \u0005[אוי שמתה אותה אשה]!\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אם כן, הוה\u0004 \u0005[הריהי]\u0006 בכלל \u0003מצוה מחמת מיתה, ומצוה מחמת מיתה\u0004 — \u0003חוזר,\u0004 גם כשאינו נותן את כל נכסיו. לפי שניכר הדבר שאינו נותן אלא מפני שהוא עומד למות, ולפיכך אם עמד מחוליו חוזר בו.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים ביחס ל\u0003מתנת שכיב מרע במקצת,\u0004 כלומר, שנתן רק מקצת נכסיו. \u0003אמרוה רבנן קמיה\u0004 \u0005[אמרו חכמים לפני]\u0006 \u0003רבא משמיה\u0004 \u0005[משמו]\u0006 של \u0003מר זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב נחמן\u0004 ש\u0003אמר משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב נחמן: הרי היא\u0004 מתנה זו \u0003כמתנת בריא, והרי היא כמתנת שכיב מרע;\u0004 כיצד? \u0003הרי היא כמתנת בריא\u0004 — \u0003שאם עמד\u0004 מחוליו \u0003אינו חוזר\u0004 בו, כפי ששנינו במשנתנו, \u0003והרי היא כמתנת שכיב מרע\u0004 — ש\u0003לא בעיא\u0004 \u0005[צריכה]\u0006 \u0003קנין\u0004 אלא נקנית באמירה בלבד, לאחר המיתה.","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא, לאו אמינא לכו\u0004 \u0005[\u0006האם \u0005לא אמרתי לכם]:\u0006 \u0003לא תיתלו בוקי סריקי\u0004 \u0005[בקבוקים ריקים]\u0006 \u0003ברב נחמן,\u0004 כלומר, אל תתלו בו שמועות של שוא? \u0003הכי\u0004 \u0005[כך]\u0006 באמת \u0003אמר רב נחמן: הרי היא כמתנת בריא\u0004 לכל ענין, \u0003ובעיא\u0004 \u0005[וצריכה]\u0006 \u0003קנין.\u0004 ואם לא נעשה קנין, גם אם מת — אין היא חלה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן\u0004 ממה ששנינו במשנתנו, בענין מתנת שכיב מרע: \u0003שייר קרקע כל שהוא\u0004 — \u0003מתנתו קיימת;\u0004 \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר אפילו ש\u0003לא קנו מיניה\u0004 \u0005[קנו ממנו]?\u0006 ודוחים: \u0003לא,\u0004 מדובר כאן באופן ש\u0003קנו מיניה\u0004 \u0005[ממנו].\u0006 וחזר והקשה: \u0003אי הכי, אימא סיפא\u0004 \u0005[אם כך, אמור\u0006 את \u0005סוף\u0006 המשנה\u0005]:\u0006 אם \u0003לא שייר קרקע כל שהוא\u0004 ועמד מחוליו — \u0003אין מתנתו קיימת; ואי\u0004 \u0005[ואם]\u0006 מדובר ש\u0003קנו מיניה\u0004 \u0005[ממנו],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003אין מתנתו קיימת?\u0004","\u0003אמר להו\u0004 \u0005[לו],\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: שכיב מרע שכתב כל נכסיו לאחרים,\u0004 ולא שייר לעצמו דבר, \u0003אף על פי שקנו מידו\u0004 — אם \u0003עמד\u0004 מחוליו \u0003חוזר,\u0004 ומדוע? \u0003בידוע שלא היה מצוה אלא מחמת מיתה,\u0004 שאין אדם נותן כל נכסיו לאחרים אם הוא סבור שיחיה.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב משרשיא לרבא\u0004 ממה שמסופר: \u0003מעשה באמן של בני רוכל שהיתה חולה,\u0004 \u0003ואמרה: \"תנתן כבינתי\u0004 (מין סיכה מקושטת) \u0003לבתי\", והוא,\u0004 הכבינה, היתה \u0003ב\u0004שווי של \u0003שנים עשר מנה, ומתה\u0004 האם, \u0003וקיימו דבריה.\u0004 והרי זו מתנה במקצת היא, ובלא קנין, ובכל זאת קיימוה! השיב לו: משם אין ראיה, שכן \u0003התם\u0004 \u0005[שם]\u0006 הרי מדובר \u0003במצוה מחמת מיתה.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבינא לרבא\u0004 שאמר שמתנת שכיב מרע במקצת אינה צריכה קנין, ממה ששנינו : \u0003האומר \"תנו גט זה לאשתי ושטר שחרור זה לעבדי\", ומת\u0004 — \u0003לא יתנו\u0004 את אלה \u0003לאחר מיתה,\u0004 לפי שלאחר מיתה אין תוקף לשטרות אלה. אבל אם אמר \u0003\"תנו מנה לפלוני\", ומת\u0004 — \u0003יתנו לאחר מיתה.\u0004 הרי שמתנה בקצת אינה צריכה קנין!","\u0003וממאי\u0004 \u0005[וממה]\u0006 אני מוכיח ש\u0003לא קנו מיניה\u0004 \u0005[ממנו]?\u0006 שהרי נשנה הדבר \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003גט, מה גט לאו בר\u0004 \u0005[אינו בן]\u0006 \u0003קנין,\u0004 שאין עושין בו קנין, \u0003אף האי נמי\u0004 \u0005[זו,\u0006 מתנה \u0005גם כן]\u0006 ש\u0003לא קנו מיניה\u0004 \u0005[ממנו],\u0006 שלא עשו בה קנין! אמר לו רבא: \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 מדובר \u0003במצוה מחמת מיתה\u0004 ולכן היא נקנית לגמרי.","\u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע אמר: מצוה מחמת מיתה בעלמא בעיא\u0004 \u0005[בכלל צריך]\u0006 \u0003קנין, וכי תניא הני מתנייתא\u0004 \u0005[וכאשר שנויות אותן המשניות,\u0006 הברייתות\u0005]\u0006 מהן משמע שאין צריך קנין — מדובר בהן \u0003במחלק כל נכסיו,\u0004 \u0003דההיא\u0004 \u0005[שאותה\u0006 מתנה\u0005]\u0006 \u0003מתנת שכיב מרע שויוה\u0004 \u0005[עשו אותה],\u0006 שאינה צריכה קנין.","ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה]:\u0006 \u0003מתנת שכיב מרע במקצת בעיא\u0004 \u0005[צריכה]\u0006 \u0003קנין, ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003מת\u0004 אחר כך. ואם לא עשו קנין — יורשים זוכים בה. אם היה \u0003מצוה מחמת מיתה לא בעיא\u0004 \u0005[צריכה]\u0006 \u0003קנין, והוא\u0004 ש\u0003מת\u0004 אחר כך. והמצוה מחמת מיתה, אם \u0003עמד\u0004 מחוליו \u0003חוזר\u0004 בו, \u0003ואף על גב דקנו מיניה\u0004 \u0005[ואף על פי שעשו עמו קנין].\u0006"],["\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בבעיה הבאה: שטר של \u0003מתנת שכיב מרע שכתוב בה\u0004 גם \u0003קנין\u0004 — \u0003בי\u0004 \u0005[\u0006תלמידי \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003רב משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמרי\u0004 \u0005[אומרים]\u0006 בלשון מליצה: \u0003ארכביה אתרי ריכשי\u0004 \u0005[הרכיב אותו על שני סוסים],\u0006 כלומר, הוסיף לו תוקף כפול, \u0003ושמואל אמר: לא ידענא מאי\u0004 \u0005[איני יודע מה,\u0006 כיצד\u0005]\u0006 \u0003אדון בה,\u0004 ואני מסופק אם יש כלל תוקף למתנה זו.","ומסבירים: \u0003בי\u0004 \u0005[\u0006תלמידי \u0005בית\u0006 מדרשו של\u0005]\u0006 \u0003רב משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב אמרי\u0004 \u0005[אומרים]:\u0006 \u0003ארכביה אתרי ריכשי\u0004 \u0005[הרכיב אותו על שני סוסים],\u0006 כוונתם: \u0003הרי היא כמתנת בריא,\u0004 ו\u0003הרי היא כמתנת שכיב מרע; הרי היא כמתנת בריא\u0004 לענין זה \u0003שאם עמד\u0004 (הבריא) מחוליו \u0003אינו חוזר,\u0004 שהרי עשה קנין. \u0003הרי היא כמתנת שכיב מרע\u0004 — \u0003שאם אמר\u0004 שנותן את \u0003הלואתו לפלוני,\u0004 הרי אף על פי שאי אפשר להעביר הלוואה על ידי אמירה בלבד (אלא במעמד שלושתם), מכל מקום במתנת שכיב מרע \u0003הלואתו לפלוני.\u0004","\u0003ושמואל אמר: לא ידענא מאי\u0004 \u0005[איני יודע מה\u0006 כיצד\u0005]\u0006 \u0003אדון בה,\u0004 כוונתו היא שכיון שכתוב בה קנין הרי יש בזה כדי להטיל ספק \u0003שמא לא גמר\u0004 בדעתו \u0003להקנותו אלא בשטר,\u0004 ולא כפי שתיקנו חכמים באמירה, \u0003ו\u0004אולם, הואיל ומתנת שכיב מרע אינה חלה אלא לאחר מיתה, הרי אינו יכול לקנות, לפי ש\u0003אין שטר\u0004 חל \u0003לאחר מיתה.\u0004","\u0003ורמי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003רב\u0004 על דברי \u0003רב, ו\u0004כן מדברי \u0003שמואל\u0004 על דברי \u0003שמואל;\u0004 שכך \u0003שלח רבין משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' אבהו: הוו ידעי\u0004 \u0005[היו יודעים]\u0006 \u0003ששלח ר' אלעזר לגולה משום רבינו\u0004 (רב): \u0003שכיב מרע שאמר \"כתבו ותנו מנה לפלוני\", ומת\u0004 לאחר מכן — \u0003אין כותבין ונותנין, שמא לא גמר להקנותו אלא בשטר, ואין שטר לאחר מיתה; ו\u0004מן הצד האחר \u0003אמר רב יהודה אמר שמואל, הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003כותבין ונותנין.\u0004","ואם כן, \u0003קשיא \u0004\u0005[קשה] \u0006מדברי \u0003רב \u0004על דברי \u0003רב, \u0004וכן \u0003קשיא \u0004\u0005[קשה] \u0006מדברי \u0003שמואל \u0004על דברי \u0003שמואל! \u0004","ומשיבים: מדברי \u0003רב \u0004על דברי \u0003רב לא קשיא \u0004\u0005[קשה\u0006]: \u0003הא \u0004\u0005[זה] \u0006שהמתנה חלה — מדובר ש\u0003קנו מיניה \u0004\u0005[ממנו\u0006], \u0003הא \u0004\u0005[זה] \u0006שאמר \"כתבו ותנו\", שאמר רב שאין כותבים ונותנים — מדובר ש\u0003לא קנו מיניה \u0004\u0005[ממנו] \u0006אלא רק ציוה באמירה בלבד. מדברי \u0003שמואל \u0004על דברי \u0003שמואל לא קשיא \u0004\u0005[קשה] \u0006שכאן שאמר שכותבים ונותנים מדובר שאמר את הדברים האלה \u0003במיפה את כחו \u0004של המקבל, ושהיה נראה מדבריו שמה שאמר שיכתבו לא היה כתנאי, אלא כדי לתת למקבל יפוי כוח יתר.","וכיוצא בזה מסופר: \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003רב נחמן בר יצחק אחוריה\u0004 \u0005[אחרי]\u0006 \u0003רבא, ויתיב\u0004 \u0005[וישב]\u0006 \u0003רבא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב נחמן קא בעי מיניה\u0004 \u0005[ושאל אותו],\u0006 \u0003מי\u0004 \u0005[האם]\u0006 \u0003אמר שמואל: שמא לא גמר להקנותו אלא בשטר ואין שטר לאחר מיתה? והא\u0004 \u0005[והרי]\u0006 \u0003אמר רב יהודה אמר שמואל: שכיב מרע שכתב כל נכסיו לאחרים, אף על פי שקנו מידו\u0004 — אם \u0003עמד\u0004 מחוליו \u0003חוזר,\u0004"],["\u0003בידוע שלא היה קנין\u0004 זה \u0003אלא מחמת המיתה.\u0004 ומכאן משמע שאם לא הבריא מחוליו — נקנתה המתנה למקבל, אף על פי שעשה בה קנין, ואין חוששים שמא לא גמר להקנותו אלא לאחר מיתה! \u0003ואחוי ליה בידיה, ואשתיק\u0004 \u0005[והראה לו\u0006 רב נחמן \u0005בידו\u0006 תנועה מסויימת, \u0005ושתק\u0006 רבא\u0005].\u0006","\u0003כי קם\u0004 \u0005[כאשר עמד]\u0006 רב נחמן ממקומו, \u0003אמר רב נחמן בר יצחק לרבא: מאי אחוי\u0004 \u0005[מה הראה]\u0006 \u0003לך,\u0004 מה היתה משמעות התנועה הזו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 שדברי רב יהודה בשם שמואל נאמרו \u0003במיפה את כחו.\u0004 כלומר, כאשר בנוסף לעצם המתנה ציוה אותו שכיב מרע שיעשו קנין, כדי לייפות את כוחו של המקבל.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003מיפה את כחו? אמר רב חסדא:\u0004 כגון שאם היה זה בשטר היה כתוב בו כך: \u0003\"וקנינא מיניה מוסיף על מתנתא דא\"\u0004 \u0005[וקנינו ממנו,\u0006 מן המצוה, \u0005נוסף על מתנה זו],\u0006 שאז רואים שהקנין אינו חלק מן המתנה, אלא תוספת יפוי כוח.","ועוד בנושא זה, \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא הדין, במקרה שבו שכיב מרע \u0003כתב לזה\u0004 במתנה נכס מסוים, וחזר \u0003וכתב לזה\u0004 לאדם אחר אותו נכס עצמו — \u0003היינו דכי אתא\u0004 \u0005[זהו\u0006 המקרה \u0005שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר\u0004 עליו: \u0003דייתיקי\u0004 \u0005[צוואה]\u0006 \u0003מבטלת דייתיקי\u0004 \u0005[צוואה],\u0006 וצוואה אחרונה היא הקיימת. ואולם השאלה היא במקרה ש\u0003כתב וזיכה לזה\u0004 שעשה מעשה זיכוי נוסף בשטר, וחזר בו ו\u0003כתב וזיכה לזה\u0004 לאדם אחר, מה יהא אז הדין? \u0003רב אמר: ראשון\u0004 שבהם \u0003קנה, ושמואל אמר: שני קנה.\u0004","ומסבירים את טעמיהם: \u0003רב אמר ראשון קנה,\u0004 שמאחר שגם זיכה לו — \u0003הרי היא כמתנת בריא\u0004 שאינו יכול לחזור בה. \u0003ושמואל אמר שני קנה\u0004 — \u0003הרי היא\u0004 המתנה לראשון \u0003כ\u0004כל \u0003מתנת שכיב מרע,\u0004 שיכול לחזור בה, ולפיכך השני קנה.","ושואלים: \u0003והא אפליגו\u0004 \u0005[והרי\u0006 כבר \u0005נחלקו]\u0006 \u0003בה חדא זימנא\u0004 \u0005[פעם אחת],\u0006 \u0003במתנת שכיב מרע שכתוב בה קנין,\u0004 שלדעת רב אינו יכול לחזור בה, ולדעת שמואל אינה חלה כלל, ומדוע הם חוזרים וחולקים באותו נושא עצמו?","ומשיבים: \u0003צריכא\u0004 \u0005[צריך]\u0006 לשנות את שתיהן, \u0003דאי איתמר בהא\u0004 \u0005[שאם היה נאמר\u0006 רק \u0005בזו]\u0006 שכתוב בה קנין\u0005,\u0006 היינו אומרים: \u0003בהא קאמר\u0004 \u0005[בזו אומר]\u0006 \u0003רב\u0004 שאין המתנה חוזרת — \u0003משום\u0004 ש\u0003קנו מיניה\u0004 \u0005[ממנו],\u0006 \u0003אבל בהא\u0004 \u0005[בזו]\u0006 במקרה שלנו, ש\u0003לא קנו מיניה\u0004 \u0005[ממנו]\u0006 אלא רק זיכה לו — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003מודה ליה\u0004 \u0005[לו]\u0006 \u0003לשמואל;\u0004 ולהיפך, \u0003ואי איתמר בהא\u0004 \u0005[ואם היה נאמר\u0006 רק \u0005בזו]\u0006 במקרה שלנו, שזיכה, היינו אומרים: \u0003בהא קאמר\u0004 \u0005[בזו\u0006 דווקא \u0005אמר]\u0006 \u0003שמואל\u0004 שיכול לחזור בו, \u0003אבל בהך אימא\u0004 \u0005[בזו,\u0006 שעשה קנין, \u0005אמור]\u0006 שמא \u0003מודה ליה\u0004 \u0005[לו]\u0006 \u0003לרב\u0004 שאינו יכול לחזור בו, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו שתי המחלוקות.","ומעירים: \u0003בסורא מתנו הכי\u0004 \u0005[היו שונים\u0006 את הסוגיה הזו \u0005כך]\u0006 כמו שאמרנו. \u0003בפומבדיתא מתנו הכי\u0004 \u0005[היו שונים כך],\u0006 \u0003אמר רב ירמיה בר אבא: שלחו ליה מבי\u0004 \u0005[לו, מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב,\u0004 לאחר מותו של רב, \u0003לשמואל, ילמדנו רבינו: שכיב מרע שכתב כל נכסיו לאחרים וקנו מידו, מהו? שלח להו\u0004 \u0005[להם]:\u0006 \u0003אין אחר קנין כלום.\u0004"],["\u0003סבור מיניה\u0004 \u0005[חשבו מכך]\u0006 ש\u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 דווקא כשנותן \u0003לאחר,\u0004 שאינו יכול לחזור בו לאחר קנין ולתת לאדם אחר, \u0003אבל\u0004 אם הבריא ורוצה לחזור ולקחת \u0003לעצמו\u0004 — \u0003לא; אמר להו\u0004 \u0005[להם]\u0006 \u0003רב חסדא, כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב הונא מ\u0004העיר \u0003כופרי פירשה: בין לעצמו בין לאחרים.\u0004","וכעין זה מסופר, \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003קנו מיניה\u0004 \u0005[ממנו],\u0006 שכתב וזיכה וקנו ממנו בשעת חוליו, ואחר כך כשהבריא רצה לחזור בו, \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רב הונא, אמר\u0004 לו רב הונא: \u0003מאי איעביד\u0004 \u0005[מה אעשה]\u0006 \u0003לך,\u0004 ש\u0003לא אקנית כדמקנו אינשי\u0004 \u0005[הקנית כמו שמקנים אנשים]\u0006 והוספת יפוי כח, ולכן אינך יכול עוד לחזור בך.","מסופר: \u0003ההיא מתנתא\u0004 \u0005[מתנה אחת]\u0006 של שכיב מרע \u0003דהוה\u0004 \u0005[שהיה]\u0006 \u0003כתוב בה\u0004 שהיא ניתנת \u0003\"בחיים ובמות\"\u0004 — \u0003רב אמר: הרי היא כמתנת שכיב מרע,\u0004 ולכן אם הבריא יכול לחזור בו מן המתנה, \u0003ושמואל אמר: הרי היא כמתנת בריא,\u0004 ואינו יכול לחזור בו עוד.","ומסבירים את השיטות: \u0003רב\u0004 ש\u0003אמר הרי היא כמתנת שכיב מרע,\u0004 טעמו, \u0003מדכתיב\u0004 \u0005[מ\u0006כיון \u0005שכתוב]\u0006 \u0003בה \"במות\"\u0004 — \u0003אחר מיתה קאמר ליה\u0004 \u0005[הוא אומר לו]\u0006 שזו היתה הכוונה, כמתנת שכיב מרע, \u0003והאי דכתיב\u0004 \u0005[וזה שכתוב\u0006 בה גם\u0005]\u0006 \u0003\"בחיים\"\u0004 — \u0003סימן בעלמא\u0004 \u0005[בלבד]\u0006 כתוב, \u0003דחיי\u0004 \u0005[שיחיה],\u0006 כלומר, כדי שלא להזכיר בשטר רק מוות, כתבו לשון שיש בה איחול וסימן שיזכה לחיים.","\u0003ושמואל\u0004 ש\u0003אמר הרי היא כמתנת בריא,\u0004 טעמו, \u0003מדכתיב\u0004 \u0005[מ\u0006כיון \u0005שכתוב]\u0006 \u0003בה \"בחיים\"\u0004 — \u0003מחיים קאמר\u0004 \u0005[הוא אומר]\u0006 והמתנה חלה מעכשיו, \u0003והאי\u0004 \u0005[וזה]\u0006 ש\u0003כתוב \"ובמות\"\u0004 — כוונתו \u0003כמאן דאמר\u0004 \u0005[כמי שאומר]\u0006 \u0003\"מעתה ועד עולם\",\u0004 כלומר, הריהי של המקבל לצמיתות. \u0003אמרי נהרדעי\u0004 \u0005[אמרו\u0006 חכמי \u0005נהרדעא]:\u0006 \u0003הלכתא כוותיה\u0004 \u0005[הלכה כשיטתו]\u0006 של \u0003רב,\u0004 ומה שנאמר \"בחיים\" אינו אלא סימן טוב.","\u0003אמר רבא: ואי כתיב\u0004 \u0005[ואם כתוב]\u0006 \u0003בה\u0004 שהוא נותן את המתנה \u0003\"מחיים\u0004 ובמות \u0003\"\u0004— \u0003קנה\u0004 המקבל, ואינו יכול לחזור בו, שהרי מחיים נתנה לו.","לאחר מכן דנו חכמים בדבר, \u0003אמר אמימר: לית הלכתא כוותיה\u0004 \u0005[אין הלכה כשיטתו]\u0006 של \u0003רבא.\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר:\u0004 \u0003פשיטא\u0004 \u0005[פשוט]\u0006 שכך הוא, \u0003דהא אמרי נהרדעי הלכתא כוותיה\u0004 \u0005[שהרי אמרו\u0006 חכמי \u0005נהרדעא\u0006 ש\u0005הלכה כשיטתו]\u0006 של \u0003רב\u0004 לענין \"בחיים ובמות\". השיב לו: חידוש יש בדבר, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שבלשון \u0003\"מחיים\" מודי\u0004 \u0005[מודה]\u0006 \u0003רב,\u0004 שנותן את המתנה כעת, בעודו חי, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שהואיל והזכיר \"במוות\" כוונתו למתנת שכיב מרע, ויכול לחזור בו.","מסופר: \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 שכתב במתנתו נוסח כזה, ועמד מחוליו וביקש לחזור בו מן המתנה, \u0003דאתא לקמיה\u0004 \u0005[שבא לפני]\u0006 \u0003רב נחמן לנהרדעא. שדריה לקמיה\u0004 \u0005[שלח אותו\u0006 רב נחמן \u0005לפני]\u0006 \u0003ר' ירמיה בר אבא ל\u0004מקום הקרוי \u0003שום טמיא\u0004 כדי שיפסוק שיכול לחזור בו. \u0003אמר: הכא\u0004 \u0005[כאן]\u0006 בנהרדעא, \u0003אתרא\u0004 \u0005[מקומו]\u0006 של \u0003שמואל,\u0004 שהוא היה החכם וראש המדברים בנהרדעא, \u0003היכי נעביד כוותיה\u0004 \u0005[איך נעשה כשיטתו]\u0006 של \u0003רב\u0004 החולק על שמואל! אין זו דרך ארץ.","ועוד מסופר: \u0003ההיא\u0004 \u0005[\u0006אשה \u0005אחת]\u0006 שכתבה נוסח מתנתה בלשון \"מחיים ובמוות\", \u0003דאתאי לקמיה\u0004 \u0005[שבאה לפני]\u0006 \u0003רבא,\u0004 \u0003עבד\u0004 \u0005[עשה]\u0006 \u0003לה רבא כשמעתיה\u0004 \u0005[כשיטתו],\u0006 ופסק שכיון שכתוב \"מחיים\" אינה יכולה לחזור בה. \u0003הוה קא טרדא ליה\u0004 \u0005[היתה מטרידה אותו]\u0006 לומר שלא דן אותה יפה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא \u0003לרב פפא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב חנן,\u0004 שהיה \u0003ספריה\u0004 \u0005[סופרו]:\u0006 \u0003זיל\u0004 \u0005[לך]\u0006 \u0003כתוב לה\u0004 פסק שהדין עימה, \u0003וכתוב בה\u0004 באותו הפסק כלשון המשנה \u0003\"שוכר עליהן או מטען\",\u0004 לרמוז שאין זו הכוונה האמיתית בפסק הדין, אלא רק הטעיה, כדי לדחות את בעל הפסק. אבל אותה אשה הבינה, ו\u0003אמרה\u0004 בלשון קללה: \u0003ליטבע ארביה\u0004 \u0005[שתטבע ספינתו]!\u0006 \u0003אטעויי קא מטעית לי\u0004 \u0005[להטעות אותי אתה בא]!\u0006 ומספרים: \u0003אמשינהו למניה\u0004 \u0005[טבלו את בגדיו]\u0006 של \u0003רבא במיא\u0004 \u0005[במים],\u0006 כדי שתתקיים בכך הקללה שלה, ולא תטבע ספינתו, \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003לא איפרק מטיבעא\u0004 \u0005[ניצול מטביעה],\u0006 שטבעה ספינתו כתוצאה מקללה זו.","\u0003לא כתב בה\u0004 במתנתו שהיה \u0003שכיב מרע,\u0004 ולאחר זמן נחלקו: \u0003הוא\u0004 הנותן \u0003אומר \"שכיב מרע הייתי\"\u0004 ולכן בטלה המתנה כשהבראתי, \u0003והן\u0004 המקבלים \u0003אומרים \"בריא היית\"\u0004 ומתנה גמורה היתה — \u0003צריך\u0004 הנותן \u0003להביא ראיה ששכיב מרע היה,\u0004 כדי לחזור בו מן המתנה, אלו \u0003דברי ר' מאיר; וחכמים אומרים: המוציא מחברו עליו הראיה,\u0004 וכיון שהקרקע עדיין ברשות הנותן — צריכים המקבלים להוכיח שיש להם זכות עליה.","מסופר: \u0003ההוא מתנתא דהוה כתב בה\u0004 \u0005[\u0006שטר \u0005מתנה אחד שהיה כתוב בו]\u0006 נוסח זה המורה שהיה שכיב מרע: \u0003\"כד הוה קציר ורמי בערסיה\"\u0004 \u0005[\"כאשר היה חולה ומוטל במיטתו\"],\u0006 \u0003ו\u0004אולם \u0003לא כתב\u0004 \u0005[היה כתוב]\u0006 \u0003בה\u0004 ההמשך של הנוסח הרגיל שכותבים במתנת שכיב מרע: \u0003\"ומגו מרעיה איפטר לבית עולמיה\u0004 \u0005[ומתוך חוליו נפטר לבית עולמו]\u0006 \u0003\",\u0004 והיו יורשיו טוענים שאכן חולה היה כאשר כתב נוסח זה, ואולם לאחר מכן הבריא, ובטלה מתנתו."],["\u0003אמר רבה: הרי\u0004 לבסוף \u0003מת\u0004 האיש, \u0003והרי קברו מוכיח עליו,\u0004 ואם כן אנו צריכים להניח כי לא הבריא ממחלתו ומת בה, ומתנתו קיימת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003ומה ספינה\u0004 שטבעה בים, \u0003שרובן\u0004 של הנוסעים בספינות שטובעות הם \u0003לאבד\u0004 — בכל זאת מפני הספק אם הוא חי או מת, מחמירים בכל דבר השייך אליו, ו\u0003נותנין עליהן,\u0004 על האדם ששמעו שטבע בספינה, גם \u0003חומרי חיים ו\u0004גם \u0003חומרי מתים,\u0004 כגון שאין אשתו מותרת להינשא לאחר, שמא הוא חי. ואם כהן הוא — אסורה אשתו (בת ישראל) באכילת תרומה, שמא הוא מת. \u0003חולין, שרוב חולין לחיים\u0004 — \u0003לא כל שכן\u0004 שעלינו להניח שהבריא מחוליו, ומתנתו בטלה?","\u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: כמאן אזלא הא שמעתא\u0004 \u0005[כ\u0006דעת \u0005מי הולכת הלכה זו]\u0006 של \u0003רבה?\u0004 — הריהי \u0003כ\u0004שיטת \u0003ר' נתן. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 בענין מי שנתן נכסיו, והוא טוען ששכיב מרע היה ורצונו לבטלה, והמקבלים טוענים שבריא היה, ואינו יכול לחזור בו, \u0003מי מוציא מיד מי? הוא\u0004 הנותן, הטוען שהיה שכיב מרע \u0003מוציא מידיהן בלא ראיה,\u0004 שאינו צריך להוכיח דבר, לפי שהנכסים היו בחזקתו, \u0003והן\u0004 המקבלים \u0003אין מוציאין מידו אלא בראיה,\u0004 אלו \u0003דברי ר' יעקב.\u0004","\u0003ר' נתן אומר: אם בריא הוא\u0004 עכשיו — \u0003עליו להביא ראיה שהיה שכיב מרע\u0004 בשעה שנתן את המתנה, \u0003אם שכיב מרע הוא\u0004 עכשיו — \u0003עליהן להביא ראיה שבריא היה.\u0004 וזה הוא הבסיס לשיטת רבה, שהולכים אחרי המצב בהווה, ומניחים שכך היה גם קודם.","\u0003אמר ר' אלעזר: ול\u0004ענין \u0003טומאה\u0004 יש לדון \u0003כ\u0004אותה \u0003מחלוקת;\u0004 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003בקעה\u0004 (שדה) \u0003בימות החמה\u0004 — הרי היא נחשבת \u0003רשות היחיד ל\u0004דיני \u0003שבת,\u0004 שאסור לטלטל ממנה לרשות הרבים, \u0003ורשות הרבים ל\u0004ענין דיני \u0003טומאה,\u0004 שספק טומאה שבה — טהור, לפי שבפועל רבים מהלכים במקום זה.","\u0003בימות הגשמים\u0004 שאין רבים הולכים בבקעה — הריהי \u0003רשות היחיד לכאן ולכאן,\u0004 כלומר, לשבת ולטומאה. ולכן לדעת ר' יעקב נכנס אדם לבקעה שהיתה בה טומאה, ויש לו ספק אם היה זה בימות החמה או בימות הגשמים — דנים אותו לפי ההווה, כלומר, הזמן ששואל מה דינו, אם שאל בימות החמה הרי זה נדון כספק טומאה ברשות הרבים, ואם שאל בימות הגשמים דנים אותו כרשות היחיד.","ובענין זה \u0003אמר רבא: לא שנו\u0004 שדנים לפי ההווה, \u0003אלא שלא עברו עליו ימות הגשמים, אבל\u0004 אם \u0003עברו עליו\u0004 כבר \u0003ימות הגשמים\u0004 — הרי זה \u0003רשות היחיד לכאן ולכאן\u0004 (לשבת וטומאה), למרות שעכשיו, בזמן שהוא שואל, הרי זה ימות החמה.","שנינו במשנה ש\u0003חכמים אומרים: המוציא מחבירו עליו הראיה.\u0004"],["ושואלים: \u0003ראיה\u0004 זו שאמרו חכמים שצריכים מקבלי המתנה להביא, \u0003במאי\u0004 \u0005[במה]?\u0006 \u0003רב הונא אמר: ראיה בעדים\u0004 שיעידו שהנותן היה בריא בשעת המתנה; \u0003רב חסדא ורבה בר רב הונא אמרי\u0004 \u0005[אומרים]:\u0006 \u0003ראיה בקיום השטר,\u0004 שרק צריכים לאשר את חתימות העדים שבשטר, לוודא ששטר אמיתי הוא.","ומסבירים לפי זה את שיטותיהם של ר' מאיר וחכמים במשנה: \u0003רב הונא\u0004 ש\u0003אמר\u0004 כי \u0003ראיה בעדים,\u0004 לדעתו \u0003קא מיפלגי בפלוגתא\u0004 \u0005[חלוקים הם במחלוקת]\u0006 של \u0003ר' יעקב ור' נתן\u0004 בברייתא שבעמוד הקודם, ובאופן זה:","\u0003ר' מאיר\u0004 שאמר שעל הנותן להביא ראיה בעדים שהיה שהיה שכיב מרע, הוא סבור \u0003כר' נתן,\u0004 שהולכים אחר המצב הקיים, ועכשיו בריא הוא. \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 שאמרו שהמקבלים צריכים להביא ראיה בעדים שבריא היה הנותן, הם סבורים \u0003כר' יעקב,\u0004 שאמר כך במפורש","\u0003.\u0004 ואילו \u0003רב חסדא ורבה בר רב הונא אמרי\u0004 \u0005[\u0006ש\u0005אומרים]\u0006 כי ה\u0003ראיה\u0004 שמצריכים חכמים היא \u0003בקיום השטר,\u0004 לדעתם \u0003קא מיפלגי\u0004 \u0005[חלוקים הם]\u0006 ר' מאיר וחכמים) \u0003ב\u0004שאלה האם כשהחייב \u0003מודה בשטר שכתבו, צריך\u0004 התובע \u0003לקיימו,\u0004 שיבואו עדים ויעידו שחתימות העדים על השטר אמיתיות הן, ש\u0003ר' מאיר סבר\u0004 \u0005[סבור]:\u0006 אם החייב \u0003מודה בשטר שכתבו\u0004 — שוב \u0003אינו צריך\u0004 התובע \u0003לקיימו,\u0004 והרי נותן המתנה מודה שכתב את השטר, ואינו יכול עוד לפסול אותו בטענה ששכיב מרע היה. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 גם אם החייב \u0003מודה בשטר שכתבו\u0004 — בכל זאת \u0003צריך לקיימו\u0004 ועל המקבל לקיים את השטר.","ושואלים: אם בזה נחלקו, \u0003והא איפליגו בה חדא זימנא\u0004 \u0005[והרי\u0006 כבר \u0005נחלקו בכך פעם אחת]!\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 עדים שקיימו חתימות ידיהם על השטר, אלא שטענו כי היו פסולים אז לעדות — \u0003אין נאמנין לפוסלו,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים: נאמנין!\u0004","ודוחים: \u0003צריכא\u0004 \u0005[צריכה]\u0006 המחלוקת להיאמר בשני המקרים, \u0003דאי איתמר\u0004 \u0005[שאם היתה נאמרת]\u0006 רק \u0003ההיא,\u0004 בעדים שפסלו עדות עצמם, היינו אומרים: \u0003בההיא קאמרי רבנן\u0004 \u0005[באותה\u0006 הלכה \u0005אומרים חכמים]\u0006 שנאמנים הם, \u0003משום דאלימי\u0004 \u0005[שתקיפים],\u0006 גדול כוחם של \u0003עדים\u0004 \u0003ומרעי שטרא\u0004 \u0005[ו\u0006הם יכולים \u0005להרע\u0006 תוקפו של \u0005שטר]\u0006 ואף שטר מקויים, \u0003אבל הכא\u0004 \u0005[כאן],\u0006 \u0003הוא,\u0004 נותן המתנה, \u0003דלאו כל כמיניה\u0004 \u0005[שאין כל זה בכוחו]\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא\u0004 יהיה נאמן לערער על השטר.","ומן הצד השני, \u0003ואי איתמר בהא\u0004 \u0005[ואם היה נאמר\u0006 רק \u0005בזו],\u0006 במקרה שלנו, הייתי אומר \u0003בהא קאמר\u0004 \u0005[בזו\u0006 דווקא \u0005אמר]\u0006 \u0003ר' מאיר\u0004 שאינו יכול לערער על השטר אם הודה שכתבו. \u0003אבל בהך\u0004 \u0005[באחרת,\u0006 בעדים\u0005]\u0006 שהודו שזהו כתב ידם, \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003מודה להו לרבנן\u0004 \u0005[להם לחכמים]\u0006 שיכולים לפסול את השטר, על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שתיאמר המחלוקת בשני מקרים.","\u0003וכן\u0004 באותו ענין עצמו \u0003אמר רבה: ראיה\u0004 זו, שהצריכו חכמים במשנתנו את המקבלים, היא \u0003בעדים,\u0004 שיעידו שהנותן היה בריא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: מאי טעמא\u0004 \u0005[מה טעם\u0006 הדבר\u0005]?\u0006 \u0003אי נימא מדכולהו כתיב בהו\u0004 \u0005[אם תאמר מפני שבכולם,\u0006 בכל השטרות\u0005, כתוב בהם]:\u0006 \u0003\"כד הוה\u0004 \u0005[כאשר היה]\u0006 \u0003מהלך על רגלוהי בשוקא\u0004 \u0005[רגליו בשוק]\u0006 \u0003\",\u0004 לומר שמתנה זו מתנת בריא, \u0003ובהא\u0004 \u0005[ובזו]\u0006 \u0003לא כתיב\u0004 \u0005[כתוב]\u0006 \u0003בה\u0004 נוסח זה — על כן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003שכיב מרע הוי\u0004 \u0005[היה],\u0006 וצריך המקבל להביא ראיה שבריא היה — \u0003אדרבה,\u0004 אתה יכול לומר להיפך, \u0003מדכולהו כתיב בהו\u0004 \u0005[מתוך שבכולם,\u0006 בכל צוואת שכיב מרע, \u0005כתוב בהן]:\u0006 \u0003\"כד קציר ורמי בערסיה\"\u0004 \u0005[\"כאשר היה חולה ומוטל במיטתו\"],\u0006 \u0003והא\u0004 \u0005[ו\u0006שטר \u0005זה]\u0006 \u0003לא כתיב בה\u0004 \u0005[כתוב בו\u0006 כך\u0005],\u0006 \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003בריא הוי\u0004 \u0005[היה],\u0006 ועל הנותן להביא ראיה ששכיב מרע היה!","ענה לו רבה: כאן, \u0003איכא למימר הכי ואיכא למימר הכי\u0004 \u0005[אפשר לומר כך ואפשר לומר כך],\u0006 על כן אין להוכיח דבר מנוסח שטר זה, ומשום ספק זה \u0003אוקי ממונא בחזקת מריה\u0004 \u0005[העמד\u0006 את \u0005הממון בחזקת בעליו\u0006 הראשונים\u0005].\u0006","ומעירים: \u0003ו\u0004מחלוקת זאת בפירוש דעת חכמים שבמשנה, הריהי שנויה \u0003בפלוגתא\u0004 \u0005[במחלוקת],\u0006 אמוראים אחרים, ש\u0003ר' יוחנן אמר: ראיה\u0004 שאמרו היא \u0003בעדים, ור' שמעון בן לקיש אמר: ראיה\u0004 היא \u0003בקיום השטר.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' יוחנן לר' שמעון בן לקיש\u0004 ממה ששנינו: \u0003מעשה בבני ברק באחד שמכר בנכסי אביו\u0004 שהוריש לו, \u0003ומת, ובאו בני משפחה\u0004 יורשיו של אותו איש, \u0003וערערו לומר: קטן היה בשעת מיתה\u0004 ולכן אין מכירתו נחשבת, \u0003ובאו ושאלו את ר' עקיבא: מהו לבודקו?\u0004 האם מותר להוציאו מן הקבר לבדוק אם היו בו סימני בגרות או לא? \u0003אמר להם: אי\u0004 (אין) \u0003אתם רשאים לנוולו\u0004 מפני צורך הממון שלכם. \u0003ועוד, סימנין\u0004 של בגרות \u0003עשויין להשתנות לאחר מיתה\u0004 ולהראות כאילו הוא גדול, למרות שלא היה כזה. ואם כן לא תהיה מכאן ראיה, ונמצא מתנוול לחינם."],["ומעתה, \u0003בשלמא לדידי דאמינא\u0004 \u0005[נניח ל\u0006שיטתי \u0005שלי שאומר אני]\u0006 כי לדעת חכמים במשנתנו צריכים המקבלים להביא \u0003ראיה בעדים\u0004 שבריא היה הנותן, הרי גם במקרה זה, \u0003כיון\u0004 ש\u0003אמר\u0004 ר' עקיבא \u0003ללקוחות: אייתו\u0004 \u0005[הביאו]\u0006 \u0003עדים, ולא אשכחו\u0004 \u0005[מצאו],\u0006 \u0003היינו דקא אתו\u0004 \u0005[זהו\u0006 הטעם \u0005שבאו]\u0006 \u0003ואמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מהו לבודקו. אלא לדידך דאמרת\u0004 \u0005[ל\u0006שיטתך \u0005שלך שאתה אומר]:\u0006 \u0003ראיה בקיום השטר\u0004 די בה כדי להוציא את המתנה, בלא עדים, הרי גם במקרה זה \u0003למה להו\u0004 \u0005[להם]\u0006 ללקוחות \u0003לבודקו? לקיימו שטרייהו ולוקמו בנכסי\u0004 \u0005[שיקיימו\u0006 את \u0005שטריהם ויעמדו בנכסים]!\u0006","דחה ריש לקיש את ההוכחה: \u0003מי סברת\u0004 \u0005[האם סבור אתה]\u0006 \u0003נכסי\u0004 \u0005[\u0006ש\u0005הנכסים]\u0006 \u0003בחזקת בני משפחה קיימי\u0004 \u0005[\u0006היו \u0005עומדים],\u0006 \u0003וקא אתו\u0004 \u0005[ובאו]\u0006 \u0003לקוחות ומערערי\u0004 \u0005[ומערערים]\u0006 ותובעים אותם? \u0003נכסי\u0004 \u0005[הנכסים]\u0006 \u0003בחזקת לקוחות קיימי\u0004 \u0005[\u0006היו \u0005עומדים],\u0006 \u0003וקא אתו\u0004 \u0005[ובאו]\u0006 \u0003בני משפחה וקא מערערי\u0004 \u0005[והיו מערערים],\u0006 ולגביהם ודאי אין ראיה בקיום השטר, שהרי הם טוענים שפסול הוא. אלא רק אם יוכיחו בעדים (או על ידי בדיקה) שקטן היה.","ומעירים: \u0003הכי נמי מסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לפרש את הדברים, \u0003מדקאמר להו\u0004 \u0005[ממה שאמר להם]\u0006 ר' עקיבא: \u0003אי\u0004 (אין) \u0003אתם רשאים לנוולו, ואישתיקו\u0004 \u0005[ושתקו].\u0006 \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ש\u0003בני משפחה קא מערערי\u0004 \u0005[הם המערערים],\u0006 \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003אישתיקו\u0004 \u0005[שתקו],\u0006 שהסכימו שאין לנוולו. \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 ש\u0003לקוחות קא מערערי\u0004 \u0005[הם המערערים],\u0006 \u0003אמאי שתקי\u0004 \u0005[מדוע\u0006 הם \u0005שותקים]?\u0006 \u0003לימרו ליה\u0004 \u0005[שיאמרו לו]:\u0006 \u0003אנן זוזי יהבינן ליה, לינוול ולינוול\u0004 \u0005[אנו כסף נתננו לו, שיתנוול ויתנוול]\u0006 ולא איכפת לנו!","ודוחים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום הא\u0004 \u0005[כך]\u0006 \u0003לא איריא\u0004 \u0005[שייך],\u0006 אין זו הוכחה, \u0003הכי קאמר להו\u0004 \u0005[כך אמר להם]\u0006 ר' עקיבא: \u0003חדא\u0004 \u0005[אחת],\u0006 \u0003דאי\u0004 \u0005[שאין]\u0006 \u0003אתם רשאים לנוולו. ועוד, וכי תימרו זוזי שקל, לינוול ולינוול\u0004 \u0005[ואם תאמרו\u0006 ש\u0005כסף לקח,\u0006 ולכן \u0005שיתנוול ויתנוול]\u0006 — מכל מקום אין טעם לעשות זאת משום ש\u0003סימנים עשויין להשתנות לאחר מיתה.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 המשך דיון בענין זה. \u0003שאל ר' שמעון בן לקיש את ר' יוחנן, זו ששנויה במשנת בר קפרא\u0004 (קובץ ברייתות שסידר): \u0003הרי שהיה\u0004 פלוני \u0003אוכל\u0004 (נהנה) מפירות \u0003שדה ובא\u0004 (ונמשך כך) \u0003בחזקת שהיא שלו, וקרא עליו אחד ערער לומר \"שלי היא\", והוציא זה\u0004 המחזיק \u0003את אונו\u0004 (שטרו) \u0003לומר: \"שמכרתה לי\" או: \"שנתתה לי במתנה\", אם אמר\u0004 המערער: \u0003\"איני מכיר בשטר זה מעולם\",\u0004 כלומר, השטר הזה מזוייף — \u0003יתקיים השטר בחותמיו,\u0004 ואם יעידו העדים שזו חתימתם — ימשיך זה להחזיק בשדה.","\u0003אם אמר\u0004 המערער: אמנם העדים חתמו עליו, אבל \u0003שטר פסים הוא זה,\u0004 כלומר, שטר שנעשה רק למראית עין, \u0003או שטר אמנה\u0004 שנעשה כראוי, \u0003שמכרתי לך ו\u0004אולם \u0003לא נתת לי דמים\u0004 (כסף) ולכן בטל המכר, \u0003אם יש עדים\u0004 שלא היה לשטר זה תוקף — \u0003הלך\u0004 (לך) \u0003אחר עדים, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003הלך אחר השטר.\u0004","ומעתה, לפירושך, שלדעת חכמים במשנתנו אין די בקיום השטר כדי להוציא את המתנה מן הנותן, \u0003לימא\u0004 \u0005[האם נאמר]\u0006 ששיטת \u0003ר' מאיר היא\u0004 ברייתא זו, ש\u0003אמר:\u0004 נתבע ה\u0003מודה בשטר שכתבו אינו צריך\u0004 מי שמחזיק בו \u0003לקיימו, ולא\u0004 שיטת \u0003רבנן\u0004 \u0005[חכמים]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003לא\u0004 כך הוא, \u0003שאני אומר: דברי הכל\u0004 היא ש\u0003מודה בשטר שכתבו אינו צריך לקיימו.\u0004 והקשה לו ריש לקיש: \u0003והא מיפלג פליגי\u0004 \u0005[והרי חלוקים\u0006 חכמים בכך\u0005]!\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 שטר שהעדים מודים שחתמו עליו, אלא שטוענים שהיו פסולים לעדות באותה שעה, ופסול הוא — \u0003אין נאמנין לפוסלו,\u0004 אלו \u0003דברי ר' מאיר, וחכמים אומרים: נאמנין!\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003אי\u0004 \u0005[אם]\u0006 \u0003עדים\u0004 נאמנים לפסול שטר שהודו שכתבוהו, משום שהם בעדותם \u0003אלימי ומרעי שטרא\u0004 \u0005[חזקים ויכולים להרע\u0006 תוקפו של \u0005שטר],\u0006 \u0003איהו כל כמיניה\u0004 \u0005[הוא זה בכוחו],\u0006 לערער על שטר כתוב שהוא מודה בו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 ריש לקיש, \u0003והלא משמך אמרו\u0004 באותו מעשה בבני ברק: \u0003יפה ערערו בני משפחה\u0004 על תוקפו של השטר, למרות שגם הם הודו שאכן נכתב על ידי קרובם שמת! הרי שצריך התובע לקיימו! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זו אלעזר\u0004 תלמידי \u0003אמרה\u0004 בשמי, \u0003אני\u0004 עצמי \u0003לא אמרתי דבר זה מעולם.\u0004","\u0003אמר ר' זירא: אם יכפור ר' יוחנן בר' אלעזר תלמידו,\u0004 ויטען שלא אמר לו מה שאמר בשמו, האם \u0003יכפור\u0004 גם \u0003בר' ינאי רבו\u0004 שאמר לו אותם דברים עצמם? שכך היה מעשה, ש\u0003אמר ר' ינאי אמר רבי: מודה בשטר שכתבו אינו צריך לקיימו, ואמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' יוחנן\u0004 לר' ינאי: \u0003רבי,\u0004 וכי \u0003לא משנתנו היא זו\u0004 העוסקת בענין זה, ומשמע ממנה היפך הדברים? ששנינו, \u0003וחכמים אומרים: המוציא מחבירו עליו הראיה,\u0004 והוסיף ר' יוחנן: ו\u0003אין ראיה אלא בקיום השטר!\u0004 הרי שר' יוחנן עצמו סבור כי לדעת חכמים, מודה בשטר שכתבו — צריך לקיימו, וכיצד יכול היה לומר שאין חולקים בדבר?","ותירץ ר' זירא: \u0003ברם\u0004 (ובאמת) \u0003נראין דברי רבינו\u0004 (רב) \u0003יוסף,\u0004 ש\u0003אמר רבינו יוסף אמר רב יהודה אומר שמואל\u0004 שיש להפוך את השיטות, ולומר: \u0003זו\u0004 הברייתא ששנה בר קפרא, ולפיה הולכים אחר השטר כפי שהוא — \u0003דברי חכמים\u0004 היא, שאין צריך לקיים שטר שהודה בו הנתבע. \u0003אבל ר' מאיר אומר: מודה בשטר שכתבו שצריך לקיימו.\u0004 \u0003ו\u0004לפי זה \u0003מאי\u0004 \u0005[מהו]\u0006 שאמר ר' יוחנן: \u0003דברי הכל\u0004 מודה בשטר שכתבו אין צריך לקיימו? משום ש\u0003דרבנן\u0004 \u0005[ש\u0006דברי \u0005חכמים]\u0006 \u0003לגבי ר' מאיר\u0004 אפשר לומר ש\u0003דברי הכל היא.\u0004","ומקשים: \u0003והא איפכא תנן\u0004 \u0005[והרי ההיפך שנינו\u0006 במשנתנו\u0005],\u0006 \u0003וחכמים אומרים: המוציא מחבירו עליו הראיה,\u0004 הרי שצריך לקיים את השטר! ואומרים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את השיטות במשנה, שר' מאיר הוא שאומר כן. ומקשים עוד: \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 עדים האומרים שהיו פסולים כשחתמו על השטר — \u0003אין נאמנין לפוסלו,\u0004 אלו \u0003דברי ר' מאיר, וחכמים אומרים: נאמנין,\u0004 הרי שלדעת חכמים צריך לקיימו! ואומרים: גם בזו \u0003איפוך\u0004 \u0005[הפוך]\u0006 את השיטות. ונמצא אם כן, כי לדעת ר' יוחנן נחלקו במשנתנו האם צריך מקבל המתנה לקיים את השטר, ומה ששנינו בדברי חכמים: המוציא מחבירו עליו הראיה — בקיום השטר אמורים הדברים.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 לעיל \u0003ר' יוחנן ראיה בעדים קאמר\u0004 \u0005[אמר]!\u0006 ואומרים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 גם את זו, שר' יוחנן הוא שאמר ראיה בקיום השטר, וריש לקיש אמר בעדים. ואומרים אם כן: \u0003לימא, ליפוך נמי תיובתא\u0004 \u0005[נהפוך גם\u0006 את \u0005הקושיה]\u0006 שהקשה ר' יוחנן לריש לקיש ממעשה בני ברק, ואמור שריש לקיש הוא שהקשה? ודוחים: \u0003לא,\u0004 זו אין צריך להפוך,"],["\u0003הכי קאמר ליה\u0004 \u0005[כך אמר לו]\u0006 \u0003ר' יוחנן לר' שמעון בן לקיש: בשלמא לדידי דאמינא\u0004 \u0005[נניח ל\u0006שיטתי \u0005שלי שאני אומר]\u0006 \u0003ראיה בקיום השטר\u0004 די לה כדי להוציא מיד הנותן (או יורשיו), \u0003היינו דמשכחת לה דנחתי\u0004 \u0005[זהו שאתה יכול למצוא אותה\u0006 אפשרות \u0005שיורדים]\u0006 \u0003לקוחות לנכסים,\u0004 לפי שקיימו את השטר, והוחזקו הנכסים בידם. ובני המשפחה רצו לבודקו כדי להוציא מידם. \u0003אלא לדידך דאמרת\u0004 \u0005[ל\u0006שיטתך \u0005שלך שאתה אומר]\u0006 ש\u0003ראיה\u0004 שצריך כדי להוציא מיד הנותן היא \u0003בעדים, היכי משכחת לה דנחתי\u0004 \u0005[איך אתה מוצא אותה\u0006 אפשרות \u0005שירדו]\u0006 \u0003לקוחות בנכסים?\u0004 והרי לא היתה בידם כל ראיה!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מודינא\u0004 \u0005[מודה אני]\u0006 \u0003לך בערער\u0004 של \u0003בני משפחה דלאו\u0004 \u0005[שלא]\u0006 \u0003ערער הוא\u0004 כנגד השטר המצוי ביד הלקוחות, ומשום כך יכולים היו הלקוחות לרדת לנכסים. ומדוע? — שהרי \u0003מאי קאמרי\u0004 \u0005[מה הם אומרים]\u0006 בני המשפחה, כשהם רוצים לעכב את הלקוחות שהשטר בידם? ש\u0003קטן היה,\u0004 ואולם \u0003חזקה\u0004 היא ש\u0003אין העדים חותמין על השטר אלא אם כן נעשה\u0004 הנותן \u0003גדול.\u0004 אבל במשנתנו, טענת הנותן שהיה שכיב מרע — יש בה ממש, שהרי אין חזקה כזו כנגדה, ולפיכך צריך המקבל להביא ראיה שהיה הנותן בריא.","מתוך שהובא אותו מעשה בבני ברק, דנים בענין שהובא בו. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שחלקו בשאלה: \u0003קטן, מאימתי מוכר\u0004 קרקעות \u0003בנכסי אביו\u0004 שמת ותהא מכירתו חלה? \u0003רבא אמר\u0004 בשם \u0003רב נחמן:\u0004 מ\u0003בן שמנה עשרה שנה\u0004 ואילך, \u0003ורב הונא בר חיננא אמר\u0004 בשם \u0003רב נחמן: מבן עשרים שנה.\u0004 ומעירים: \u0003והא\u0004 \u0005[וזה]\u0006 שאמר \u0003רבא לאו\u0004 \u0005[לא]\u0006 \u0003בפירוש איתמר\u0004 \u0005[נאמר]\u0006 \u0003אלא מכללא איתמר\u0004 \u0005[מכלל\u0006 הדברים \u0005נאמר]\u0006 שכך הסקנו מדבריו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003ר' זירא\u0004 ממה ששנינו בברייתא: \u0003מעשה בבני ברק באחד שמכר בנכסי אביו ומת, ובאו בני משפחה וערערו לומר: קטן היה בשעת מיתה, ובאו ושאלו את ר' עקיבא: מהו לבודקו? אמר להם: אי אתם רשאין לנוולו. ועוד, סימנין עשויין להשתנות לאחר מיתה.\u0004 ומעתה, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003בן שמנה עשרה שנה\u0004 רשאי למכור,"],["\u0003היינו דקאתו\u0004 \u0005[זהו\u0006 הטעם \u0005שבאו]\u0006 \u0003ואמרו ליה\u0004 \u0005[לו]:\u0006 \u0003מהו לבודקו,\u0004 שמא עדיין לא הביא שתי שערות למרות שהיה בן שמונה עשרה, ולכן מכרו בטל. \u0003אלא אי אמרת\u0004 \u0005[אם אתה אומר]\u0006 ש\u0003מבן עשרים\u0004 רשאי למכור, \u0003כי בדקו ליה מאי הוי\u0004 \u0005[כאשר בודקים אותו מה נהיה,\u0006 מה בכך\u0005]?\u0006 \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003בן עשרים שלא הביא\u0004 עדיין \u0003שתי שערות\u0004 — \u0003יביאו ראיה שהוא בן עשרים, ו\u0004אם עשו כן אין הוא עוד בכלל קטן, אלא \u0003הוא הסריס,\u0004 שהוא \u0003לא חולץ ולא מיבם\u0004 את אשת אחיו שמת, אבל לעניינים אחרים דינו כגדול!","ודוחים: \u0003לאו איתמר עלה\u0004 \u0005[האם לא נאמר על כך]\u0006 ש\u0003אמר ר' שמואל בר רב יצחק אמר רב: והוא שנולדו בו סימני סריס?\u0004 כלומר, שלא העדר השערות בלבד גורם לכך, אלא צריך שיהיו בו גם שאר סימנים של סריס. ואם לא כן — קטן הוא לכל ענין. ונמצא לענייננו, שגם אם היה המוכר בן עשרים היתה משמעות לבדיקה. \u0003אמר רבא: דיקא נמי\u0004 \u0005[מדויק גם כן]\u0006 בלשון אותה משנה שכך הוא, \u0003דקתני\u0004 \u0005[ששנה]:\u0006 \u0003והוא הסריס,\u0004 כלומר, לא די שיהא בן עשרים, אלא מדובר במי שברור שהוא סריס. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","ושואלים: \u0003וכי\u0004 \u0005[וכאשר]\u0006 \u0003לא נולדו לו סימני סריס, עד כמה\u0004 ממתינים לו שיביא שתי שערות כדי שייחשב גדול? \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא\u0004 בברייתא: \u0003עד רוב שנותיו\u0004 (אחרי שלושים וחמש שנה). \u0003כי אתא\u0004 \u0005[כאשר היה בא]\u0006 מקרה כזה \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003ר' חייא, אי כחיש אמר להו\u0004 \u0005[אם היה רזה היה אומר להם]:\u0006 \u0003ליברי\u0004 \u0005[הבריאו,\u0006 השמינו \u0005אותו]\u0006 שמא מחמת זה אין בו סימנים, \u0003ואי אברי אמר להו\u0004 \u0005[ואם היה בריא,\u0006 שמן, \u0005היה אומר להם]:\u0006 \u0003ליכחוש\u0004 \u0005[שירזה],\u0006 לפי \u0003דהני סימני זמנין דאתו\u0004 \u0005[שאותם סימנים פעמים ש\u0006הם \u0005באים]\u0006 \u0003מחמת כחישותא\u0004 \u0005[רזון],\u0006 \u0003זמנין דאתו\u0004 \u0005[פעמים ש\u0006הם \u0005באים]\u0006 \u0003מחמת בריותא\u0004 \u0005[השמנה].\u0006","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]:\u0006 \u0003תוך זמן,\u0004 כלומר, בתוך שנת שמונה עשרה או שנת עשרים עצמה, מה דינה לענין שיוכל הקטן למכור בנכסי אביו? \u0003כלפני זמן, או כלאחר זמן? רבא אמר\u0004 בשם \u0003רב נחמן:\u0004 \u0003תוך זמן כלפני זמן. רבא בר רב שילא אמר\u0004 בשם \u0003רב נחמן: תוך זמן כלאחר זמן.\u0004","ומעירים: \u0003והא\u0004 \u0005[וזה]\u0006 שאמר \u0003רבא לאו\u0004 \u0005[לא]\u0006 \u0003בפירוש איתמר\u0004 \u0005[נאמר]\u0006 \u0003אלא מכללא איתמר\u0004 \u0005[מכלל\u0006 הדברים \u0005נאמר],\u0006 \u0003דההוא\u0004 \u0005[ש\u0006אדם \u0005אחד]\u0006 שהיה בגיל של \u0003תוך זמן דאזיל זבין נכסי ואתא לקמיה\u0004 \u0005[שהלך\u0006 ו\u0005מכר נכסים\u0006 של אביו \u0005ובא לפני]\u0006 \u0003רבא, אמר להו\u0004 \u0005[להם]:\u0006 \u0003לא עשה ולא כלום.\u0004 ומעירים: \u0003מאן דחזא סבר\u0004 \u0005[מי שראה סבור היה]\u0006 שהטעם היה \u0003משום\u0004 ש\u0003תוך זמן כלפני זמן, ולא היא\u0004 (אין \u0003כן הדבר),\u0004 \u0003התם שטותא יתירתא חזא ביה\u0004 \u0005[שם שטות יתירה ראה בו],\u0006 \u0003דהוה קא משחרר להו לעבדיה\u0004 \u0005[שהיה משחרר אותם את עבדיו],\u0006 ומתוך שראה שאינו בר דעת ביטל את המכירה שלו.","מסופר: \u0003שלח ליה\u0004 \u0005[לו]\u0006 \u0003גידל בר מנשיא לרבא, ילמדנו רבינו:\u0004 היתה \u0003תינוקת,\u0004 כלומר, נערה \u0003בת ארבע עשרה שנה ויום אחד\u0004 והיתה \u0003יודעת בטיב משא ומתן, מהו\u0004 דינה לענין מכירת קרקע? \u0003שלח ליה\u0004 \u0005[לו]:\u0006 \u0003אם יודעת בטיב משא ומתן\u0004 — \u0003מקחה מקח וממכרה ממכר.\u0004","ושואלים: \u0003ולישלח ליה\u0004 \u0005[ושישלח לו]\u0006 שאלה זו ב\u0003תינוק!\u0004 ומשיבים: \u0003מעשה שהיה כך היה.\u0004 ושואלים: \u0003ולישלח ליה\u0004 \u0005[ושישלח לו]\u0006 שאלה ב\u0003תינוקת בת שתים עשרה שנה ויום אחד,\u0004 שהרי מגיל זה כבר יש חזקה שבוגרת היא! ואומרים: \u0003מעשה שהיה כך היה.\u0004","ומעירים: \u0003והא\u0004 \u0005[וזה]\u0006 שנאמר בשם \u0003רבא לאו\u0004 \u0005[לא]\u0006 \u0003בפירוש איתמר\u0004 \u0005[נאמר]\u0006 \u0003אלא מכללא איתמר\u0004 \u0005[מכלל\u0006 הדברים \u0005נאמר],\u0006 \u0003דההוא\u0004 \u0005[ש\u0006אדם \u0005אחד]\u0006 שהיה \u0003פחות מבן עשרים דאזל זבין נכסי אבוהו\u0004 \u0005[שהלך\u0006 ו\u0005מכר\u0006 את \u0005נכסי אביו]\u0006 כפי שהשיב רבא ל\u0003גידל בר מנשיא,\u0004 שהדבר אפשרי במי שיודע בטיב משא ומתן. \u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רבא\u0004 ורצה לבטל את המכירה. \u0003אמרו ליה קרוביה\u0004 \u0005[לו קרוביו]\u0006 לאותו בחור שמכר נכסיו: \u0003זיל\u0004 \u0005[לך]\u0006 \u0003אכול תמרי\u0004 \u0005[תמרים]\u0006 \u0003ושדי ביה קשייתא בי\u0004 \u0005[וזרוק\u0006 את \u0005הגרעינים בבית]\u0006 \u0003רבא,\u0004 ורצו שעל ידי כך יבין רבא שאינו בר־דעת. \u0003עבד הכי\u0004 \u0005[עשה כך],\u0006 \u0003אמר להו\u0004 \u0005[להם]\u0006 רבא למתדיינים: \u0003זביניה לאו זביני\u0004 \u0005[מכירתו אינה מכירה].\u0006","\u0003כי קא כתבו ליה שטרא\u0004 \u0005[כאשר כתבו לו שטר]\u0006 של פסק דין, \u0003אמרו ליה\u0004 \u0005[לו]\u0006 ה\u0003לקוחות\u0004 לאותו מוכר, שרצו להראות שאינו טיפש: \u0003זיל אימא ליה\u0004 \u0005[לך אמור לו]\u0006 \u0003לרבא: מגלת אסתר\u0004 שהיא גדולה במידותיה, קונים אותה \u0003בזוזא\u0004 \u0005[זוז,\u0006 דינר\u0005],\u0006 \u0003שטרא דמר בזוזא\u0004 \u0005[שטר של אדוני,\u0006 שהוא קטן, קונים גם כן ב\u0005זוז]?\u0006 שזה היה שכר הסופר שכתב את השטר. \u0003אזל\u0004 \u0005[הלך]\u0006 אותו בחור \u0003אמר ליה\u0004 \u0005[לו],\u0006 לרבא כך. \u0003אמר להו\u0004 \u0005[להם]\u0006 רבא: \u0003זביניה זביני\u0004 \u0005[מכירתו מכירה].\u0006 \u0003אמרו ליה\u0004 \u0005[לו,\u0006 לרבא\u0005]\u0006 \u0003קרוביה\u0004 \u0005[קרוביו]\u0006 של אותו בחור: ה\u0003לקוחות אגמרוהו\u0004 \u0005[לימדו אותו]\u0006 לומר כן, ולא מדעתו היא! \u0003אמר להו\u0004 \u0005[להם]\u0006 רבא: מכל מקום \u0003מסברי ליה סבר\u0004 \u0005[מסבירים לו\u0006 דבר והוא \u0005מבין],\u0006 \u0003כיון דמסברי ליה וסבר\u0004 \u0005[שמסבירים לו ו\u0006הוא \u0005מבין]\u0006 — \u0003מידע ידע\u0004 \u0005[יודע\u0006 הוא\u0005]\u0006 מה הוא עושה, \u0003והאי דעבד הכי\u0004 \u0005[וזה שעשה כך]\u0006 שזרק את הגרעינים — \u0003חוצפא יתירא הוא דהוה ביה\u0004 \u0005[שהיתה בו],\u0006 ולא משום שלא הבין דבר.","ובענין מי שלא הגיע לגיל בו הוא רשאי למכור בנכסי אביו, \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: ולעדות\u0004 — \u0003עדותו עדות. אמר מר זוטרא: לא אמרן\u0004 \u0005[אמרנו]\u0006 שהוא רשאי להעיד \u0003אלא למטלטלי\u0004 \u0005[למיטלטלים],\u0006 \u0003אבל למקרקעי\u0004 \u0005[לקרקעות]\u0006 \u0003לא.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי למר זוטרא: מאי שנא מטלטלי\u0004 \u0005[מה שונה\u0006 הדבר ב\u0005מיטלטלים]\u0006 שעדותו עדות — משום \u0003דזביניה זביני\u0004 \u0005[שמכירתו מכר];\u0006 \u0003אלא מעתה, הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הפעוטות\u0004 (ילדים) — \u0003מקחן מקח וממכרן ממכר במטלטלין,\u0004 אם כן \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003עדותן עדות?\u0004 והרי קטן פסול לעדות! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם בעינא\u0004 \u0005[שם,\u0006 בעדות, \u0005אנו צריכים]\u0006 שיתקיים הכתוב \u0003\"ועמדו שני האנשים\"\u0004 (דברים יט,יז), שאנו מפרשים שהם העדים, \u0003וליכא\u0004 \u0005[ואין כאן],\u0006 שמי שאינו גדול בשנים אינו נקרא \"איש\", ולא משום חוסר דעת.","ועוד במי שאינו רשאי למכור בנכסי אביו, \u0003אמר אמימר: ומתנתו\u0004 בנכסי אביו — היא \u0003מתנה. אמר לו רב אשי לאמימר: השתא\u0004 \u0005[עכשיו]\u0006 \u0003ומה זביני\u0004 \u0005[במכר]\u0006 שהוא \u0003מקבל זוזי\u0004 \u0005[כסף]\u0006 \u0003אמרת\u0004 תיקנו חכמים \u0003דלא\u0004 \u0005[שאין]\u0006 הוא רשאי למכור, \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003מוזיל\u0004 הוא מן המחיר הראוי \u0003ומזבין\u0004 \u0005[ומוכר],\u0006 ונמצא מפסיד את נכסי אביו, \u0003כל שכן מתנה\u0004 ש\u0003לא מטי ליה\u0004 \u0005[מגיע לו,\u0006 לידיו\u0005]\u0006 \u0003ולא מידי\u0004 \u0005[כלום\u0006 בתמורה\u0005]\u0006 יש לומר שלא יוכל לתת! \u0003אמר ליה\u0004 \u0005[לו]\u0006 אמימר:"],["\u0003ולטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005],\u0006 שהדברים תלויים בתמורה שהוא מקבל לנכסים, אם \u0003זבין שוי חמשא בשיתא\u0004 \u0005[מכר שווה חמישה בשישה]\u0006 והרויח בכך, \u0003הכי נמי דזביניה זביני\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שמכירתו מכר]\u0006 מפני שהרויח בכך?","\u0003אלא,\u0004 כך צריך לומר: \u0003קים להו לרבנן\u0004 \u0003דינוקא מקרבא דעתיה גבי זוזי\u0004 \u0005[מוחזק להם לחכמים שהתינוק קרובה דעתו,\u0006 נמשך \u0005לדינרים],\u0006 שכשהוא רואה מטבעות כסף הוא חושק בהם, \u0003ואי אמרת זביניה זביני\u0004 \u0005[ואם אתה אומר\u0006 ש\u0005מכירתו\u0006 בקרקעות \u0005מכר],\u0006 \u0003זמנין דמקרקשי ליה זוזי\u0004 \u0005[פעמים שמקשקשים לו\u0006 ב\u0005מטבעות],\u0006 כדי לפתות אותו למכור, והוא \u0003אזיל מזבין לכולהו נכסי דאבוה\u0004 \u0005[הולך ומוכר\u0006 להם \u0005את כל נכסי אביו];\u0006 \u0003אבל גבי\u0004 \u0005[אצל]\u0006 \u0003מתנה,\u0004 שלא קיים בו שיקול זה, \u0003אי לאו דהוה ליה\u0004 \u0005[אם לא שהיתה לו]\u0006 \u0003הנאה מיניה\u0004 \u0005[ממנו]\u0006 \u0003לא הוה יהיב ליה\u0004 \u0005[היה נותן לו]\u0006 \u0003מתנה,\u0004 ואדרבה, \u0003אמרו רבנן\u0004 \u0005[חכמים]:\u0006 \u0003תיהוי\u0004 \u0005[תהיה]\u0006 \u0003מתנתו מתנה, דלעבידו להו מילי\u0004 \u0005[\u0006כדי \u0005שיעשו\u0006 \u0005עבורם דברים],\u0006 מפני שיודעים שאותו יתום יכול לגמול להם במתנות.","\u0003אמר רב נחמן אמר שמואל: בודקין\u0004 ילדים אף על פי שהגיעו לגיל הבגרות (שלוש עשרה בבנים ושתים עשרה בבנות) אם יש להם סימני בגרות, לענין כמה דברים: \u0003לקדושין, לגרושין, ולחליצה ולמיאונין.\u0004 \u0003ו\u0004לענין \u0003למכור בנכסי אביו\u0004 — \u0003עד שיהא בן עשרים.\u0004","ושואלים: \u0003וכיון דבדקנא\u0004 \u0005[שבדקנו\u0006 כבר\u0005]\u0006 \u0003לקדושין\u0004 ונמצא גדול, \u0003לגרושין למה לי\u0004 למה צריך לבדוק פעם שניה? ומשיבים: \u0003לא נצרכא\u0004 \u0005[הוצרכה]\u0006 להיאמר הלכה זו בגירושין \u0003אלא ל\u0004מקרה של \u0003יבום\u0004 שעשה הקטן באשת אחיו שמת, וכיצד? \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003בן תשע שנים ויום אחד שבא על יבמתו\u0004 — \u0003קנאה\u0004 בביאה. שאף שהוא קטן ואינו יכול לקדש אשה, מכל מקום מגיל זה ביאתו נחשבת לביאה ולגבי יבימתו מועיל הדבר. \u0003ו\u0004אולם \u0003אין נותן גט עד\u0004 \u0003שיגדל.\u0004 ומשום כך צריך לבדוק אותו עתה לגירושין, אף שלא היה מקום לבודקו קודם לכן בייבום. וממשיכים לבאר מה חידוש יש בכל דבר מהרשימה האמורה בדברי רב נחמן בשם שמואל.","\u0003לחליצה\u0004 — \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' יוסי,\u0004 ש\u0003אמר: \"איש\"\u0004 (שהוא בוגר) \u0003כתוב בפרשה\u0004 לענין חליצה, \u0003אבל אשה\u0004 — \u0003בין גדולה ובין קטנה\u0004 יכולה להיחלץ, שלא פירש הכתוב את גילה, על כן \u0003קא משמע לן דמקשינן\u0004 \u0005[השמיע לנו\u0006 רב נחמן בשם שמואל \u0005שמקישים,\u0006 משווים \u0005אנו]\u0006 בדין חליצה \u0003אשה לאיש,\u0004 שאף אשה הנחלצת — דווקא כשהיא גדולה, ש\u0003לא כ\u0004שיטתו זו של \u0003ר' יוסי.\u0004","\u0003ולמיאונין\u0004 — \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' יהודה,\u0004 ש\u0003אמר\u0004 שהבת היתומה, שהשיאו אותה אמה או אחיה, יכולה למאן בבעלה, ובטלים הקדושין \u0003עד\u0004 שתהיה בוגרת ממש, \u0003שירבה\u0004 שיער \u0003שחור\u0004 על הלבן במקום ערוה, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ש\u0003לא כ\u0004דברי \u0003ר' יהודה,\u0004 אלא, הגבול הוא בבגרות — בשתי שערות.","ומה שאמר רב נחמן בשם שמואל: \u0003ולמכור בנכסי אביו עד שיהא בן עשרים\u0004 — \u0003לאפוקי ממאן דאמר\u0004 \u0005[\u0006בא \u0005להוציא מ\u0006דעת \u0005מי שאומר]\u0006 \u0003בן שמנה עשרה.\u0004","ומסכמים להלכה את הדברים שנאמרו בסוגיות הללו: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]\u0006 שבן המוכר בנכסי אביו ב\u0003תוך זמן,\u0004 כלומר, בתוך שנתו העשרים, הריהו \u0003כלפני זמן,\u0004 ואינו מוכר אלא לאחר שמלאו לו עשרים שנה מלאות. \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כ\u0004מו שענה רבא לשאלת \u0003גידל בר מנשה,\u0004 שילד שהגיע לבגרות מוכר קרקעות אם הוא מבין בטיב משא ומתן.","\u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כמר זוטרא,\u0004 שכל שאינו כשר למכור בקרקעות אינו כשר להעיד בכך. \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כאמימר,\u0004 שיכול יתום לתת מתנות של קרקע מנכסי אביו לפני שהגיע לגיל עשרים. \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כרב נחמן אמר שמואל בכולהו\u0004 \u0005[בכולם]\u0006 בכל דברים שאמר, שצריך לבדוק בפועל אם הביאו הקטן או הקטנה סימני בגרות.","\u0003המחלק נכסיו על פיו\u0004 שמחלק את הנכסים שיש לו לאנשים שונים, \u0003ר' אלעזר אומר:\u0004 \u0003אחד בריא ואחד מסוכן\u0004 (נוטה למות) שמחלקים רכושם — דינם שווה, שאם אלה \u0003נכסים שיש להן אחריות\u0004 (קרקעות והדומה להם) — \u0003נקנין בכסף ובשטר ובחזקה, ושאין להן אחריות\u0004 (מיטלטלים) — \u0003אין נקנין אלא במשיכה.\u0004"],["\u0003אמרו לו: מעשה באמן של בני רוכל שהיתה חולה, ואמרה: \"תנו כבינתי\u0004 (מין סיכה מקושטת) \u0003לבתי, והיא ב\u0004שווי של \u0003שנים עשר מנה\", ומתה\u0004 האם, \u0003וקיימו את דבריה!\u0004 משמע שיכול שכיב מרע להקנות באמירה בלי קנין! \u0003אמר להן:\u0004 משם אין להביא ראיה, שכן \u0003בני רוכל\u0004 אלה בכלל ראויים ש\u0003תקברם אמן\u0004 (שימותו בחייה), שרשעים היו ולא דקדקו בדינם, ולכן נתנו את הכבינה לאחותם.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר להן ר' אליעזר לחכמים: מעשה במרוני אחד\u0004 (בן היישוב מרון) \u0003שהיה בירושלים, והיו לו מטלטלין הרבה וביקש ליתנם במתנה\u0004 לכמה בני אדם, ולא ניתן היה להקנות אותם במשיכה. \u0003אמרו לו: אין להם תקנה עד שיקנה\u0004 אותם \u0003על גב\u0004 (אגב) \u0003קרקע,\u0004","\u0003הלך ולקח\u0004 (קנה) קרקע בשיעור \u0003בית סלע אחד סמוך לירושלים,\u0004 שהיה מקום סלעי ומחירו מועט, \u0003ואמר: צפונו\u0004 של המקום הזה נתון \u0003לפלוני, ועמו מאה צאן ומאה חביות, ודרומו\u0004 נתון \u0003לפלוני\u0004 אחר \u0003ועמו מאה צאן ומאה חביות. ומת, וקיימו חכמים את דבריו.\u0004 משמע שמתנת שכיב מרע אינה מוקנית בדברים בלבד! \u0003אמרו לו: משם\u0004 מביא אתה \u0003ראיה?\u0004 אותו \u0003מרוני בריא היה\u0004 באותה שעה, ומתנתו מתנת בריא היתה ולא מתנת שכיב מרע, ולכן אינה נקנית באמירה בלבד.","שנינו במשנה, \u0003אמר להן: בני רוכל תקברם אמן וכו'.\u0004 ושואלים: \u0003מאי טעמא קא לייט להו\u0004 \u0005[מה טעם קילל אותם]?\u0006 \u0003אמר רב יהודה אמר שמואל: מקיימי קוצים בכרם היו,\u0004 שלא היו מבערים את הקוצים מן הכרם שלהם, \u0003ור' אליעזר\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו\u0006, לשיטתו\u0005],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003המקיים קוצים בכרם\u0004 ואינו עוקרם — \u0003ר' אליעזר אומר: קדש\u0004 (נאסר) באיסור כלאיים בכרם, \u0003וחכמים אומרים:\u0004 \u0003לא קדש\u0004 משום כלאי הכרם \u0003אלא\u0004 אם גדל בכרם \u0003דבר שכמוהו\u0004 אנשים \u0003מקיימין\u0004 בכוונה, ולא צמח בר שאין רוצים בו.","ולגופה של משנה זו שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 אם היה זה צמח \u0003כרכום\u0004 שגדל בכרם, \u0003חזי\u0004 \u0005[ראוי]\u0006 לתבלין ולשאר שימושים, ולכן הוא מקדש משום כלאיים, \u0003אלא קוצים למאי חזי\u0004 \u0005[למה\u0006 הם \u0005ראויים]?\u0006 \u0003אמר ר' חנינא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' אליעזר?\u0004 — \u0003שכן בערביא מקיימין קוצים בשדות ל\u0004צורך \u0003גמליהן,\u0004 ואם כן הרי זה גידול שנעשה לשם שימוש, כשאר גידולים.","\u0003אמר ר' לוי: קונין קנין משכיב מרע אפילו בשבת,\u0004 למרות שבשבת אין עושים קנין. \u0003ולא\u0004 שעושים זאת כדי \u0003לחוש לדברי ר' אליעזר\u0004 שמתנת שכיב מרע צריכה קנין, \u0003אלא\u0004 שאם החולה רוצה שיעשו קנין, אנו עושים כדבריו. וכל זאת, משום חשש \u0003שמא תטרוף דעתו עליו\u0004 אם לא יעשו כרצונו.","\u0003ר' אליעזר אומר: בשבת\u0004 — \u0003דבריו\u0004 של שכיב מרע \u0003קיימין, מפני שאין יכול לכתוב\u0004 בשבת, וחששו חכמים לטירוף דעתו אם יחשוש שמא ימות בלי שיוכל לתת, \u0003אבל לא בחול. ר' יהושע אומר: בשבת אמרו\u0004 (תיקנו חכמים) שדבריו קיימים, אף שאסור לכתוב בשבת, \u0003קל וחומר בחול\u0004 שזמן ראוי הוא לכתיבה — דבריו קיימים.","\u0003כיוצא בו\u0004 נחלקו בענין דומה: \u0003זכין לקטן,\u0004 יכול אחר לזכות עבורו, \u0003ואין זכין לגדול\u0004 — שהרי הוא יכול לזכות בעצמו. אלו \u0003דברי ר' אליעזר.\u0004 ואילו \u0003ר' יהושע אומר: לקטן אמרו\u0004 חכמים שזוכים, \u0003קל וחומר לגדול\u0004 שיש לו כח לזכות בעצמו.","שואלים: \u0003מתניתין מני\u0004 \u0005[משנתנו\u0006 כשיטת \u0005מי היא]?\u0006 ומשיבים: שיטת \u0003ר' יהודה היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' מאיר אומר, ר' אליעזר אומר:\u0004 שכיב מרע שמחלק רכושו באמירה, \u0003בחול\u0004 — \u0003דבריו קיימין, מפני שיכול לכתוב, אבל לא בשבת\u0004 משום שאין יכול לכתוב;","\u0003ר' יהושע\u0004"],["\u0003אומר: בחול אמרו\u0004 חכמים שמזכה בדיבור למרות שניתן לכתוב, \u0003וקל וחומר לשבת\u0004 שאי אפשר לכתוב בה. \u0003כיוצא בו\u0004 נחלקו בענין דומה: \u0003זכין לגדול\u0004 שיש לו כח זכיה בעצמו, \u0003ואין זכין לקטן,\u0004 אלו \u0003דברי ר' אליעזר. ר' יהושע אומר: בגדול אמרו\u0004 שזוכים עבורו, למרות שיכול לזכות לעצמו, \u0003קל וחומר לקטן\u0004 שאם לא יזכו עבורו לא יזכה בעצמו. זו היתה שיטת ר' מאיר במחלוקת זו.","ואילו \u0003ר' יהודה אומר\u0004 שכך היתה המחלוקת, ש\u0003ר' אליעזר אומר: בשבת\u0004 — \u0003דבריו קיימין, מפני שאינו יכול לכתוב, אבל לא בחול. ר' יהושע אומר: בשבת אמרו\u0004 דבריו קיימים, \u0003קל וחומר בחול\u0004 שיכול אז לכתוב. \u0003כיוצא בו, זכין לקטן ואין זכין לגדול,\u0004 אלו \u0003דברי ר' אליעזר.\u0004 ו\u0003ר' יהושע אומר: לקטן אמרו\u0004 שזוכים, \u0003קל וחומר לגדול.\u0004 והם דברי משנתנו בדיוק.","\u0003נפל הבית עליו ועל אביו, או עליו ועל מורישיו\u0004 האחרים, ומתו כל הנמצאים בבית, ואולם לא ידוע מי מהם מת קודם. \u0003והיתה עליו,\u0004 על הבן, חובת תשלום ל\u0003כתובת אשה, ו\u0004כן ל\u0003בעל חוב\u0004 שהיה הבן חייב לו כסף, ולא היה לבן כסף מעצמו, אלא מה שיכול לרשת מאביו. \u0003יורשי האב אומרים: הבן מת ראשון ואחר כך מת האב,\u0004 ומשום כך לא ירש הבן דבר, וכל הנכסים שייכים לאב, ועל האב (ויורשיו) אין כל התחייבות לשלם את הכתובה או חוב. \u0003ובעלי החוב אומרים:\u0004 לא כן, אלא \u0003האב מת ראשון ואחר כך מת הבן\u0004 ונמצא שירש הבן את נכסי אביו, ומהם הם רוצים לגבות.","כיון שלא ניתן לבירור מי מת ראשון — \u0003בית שמאי אומרים: יחלוקו\u0004 אלו ואלו ביניהם, \u0003ובית הלל אומרים:\u0004 ה\u0003נכסים\u0004 יעמדו \u0003בחזקתן\u0004 וישארו בידי יורשי האב.","משנתנו הובאה בתוך דיון על משנה אחרת, וכך \u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה: \u0003המלוה את חבירו בשטר\u0004 — \u0003גובה\u0004 את חובו גם \u0003מנכסים משועבדים\u0004 (נכסים שהיו ברשותו בזמן ההלוואה ומכר אותם). אם היה זה מלוה \u0003על ידי עדים,\u0004 שלא בשטר — \u0003גובה\u0004 המלוה רק \u0003מנכסים בני חורין\u0004 (שלא נמכרו לאחרים).","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003שמואל:\u0004 הכותב בשטר שהוא משעבד נכסים \u0003\"דאיקני\"\u0004 \u0005[שאקנה],\u0006 \u0003וקנה\u0004 נכסים לאחר כתיבת השטר, \u0003מהו\u0004 הדין בכגון זה? האם הם משתעבדים לחוב או לא? ומסבירים: \u0003אליבא\u0004 \u0005[על פי]\u0006 שיטתו של \u0003ר' מאיר\u0004 ש\u0003אמר: אדם מקנה\u0004 \u0003דבר שלא בא\u0004 עדיין \u0003לעולם\u0004 — \u0003לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 שאלה זו, ש\u0003ודאי קנה\u0004 המלוה, כלומר, שנכסים אלו משועבדים לו. שאם יכול להקנות דבר במתנה, כל שכן שחל עליו השעבוד. \u0003אלא כי תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה הרי זה \u0003אליבא דרבנן\u0004 \u0005[לשיטת חכמים],\u0006 \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]:\u0006 \u0003אין אדם מקנה דבר שלא בא לעולם,\u0004 מה יהא הדין כשכתב \"דאיקני\"?","\u0003אמר רב יוסף: תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר, ששנינו במשנה מחלוקת בענין אדם המוציא שטר חוב על חבירו, והלווה מוכיח שלאחר כתיבת השטר קנה מן המלוה קרקע. שאדמון אומר שהדבר מוכיח שכבר נפרע החוב, שאם לא כן — לא היה המלוה מוכר לו קרקע. \u0003וחכמים אומרים: זה\u0004 המלוה \u0003היה פיקח שמכר לו את הקרקע, מפני שהוא יכול\u0004 עתה \u0003למשכנו עליו\u0004 כשתובע את חובו. מכל מקום ברור שקרקע זו נקנתה לאחר שנכתב שטר החוב, ובכל זאת יכול המלוה לגבות ממנה. משמע שיש דרך שישתעבדו למלוה גם נכסים שהלווה קונה לאחר ההלוואה!","על הראיה שהביא רב יוסף ממשנה זו \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מיניה קאמר\u0004 \u0005[ממנו אמר]?\u0006 \u0003מיניה\u0004 \u0005[ממנו]\u0006 — \u0003אפילו מגלימא\u0004 \u0005[מגלימה]\u0006 ש\u0003על כתפיה\u0004 \u0005[כתפו]\u0006 הוא גובה, ובוודאי מכל דבר המצוי עתה בידו יכול לגבות! \u0003כי קא מיבעיא לן\u0004 \u0005[כאשר נשאלת לנו\u0006 השאלה\u0005]\u0006 הרי זה במקרה שכתב \u0003\"דאיקני\"\u0004 \u0005[שאקנה]\u0006 ו\u0003קנה ומכר\u0004 לאחרים, או שכתב \u0003\"דאיקני\"\u0004 \u0005[שאקנה]\u0006 ו\u0003קנה והוריש, מאי\u0004 \u0005[מה\u0006 הדין\u0005]?\u0006 האם יכול המלוה לטרוף נכסים אלה מן הקונה או היורש? ומאותה משנה לא נפתרה שאלה זו.","\u0003אמר רב חנא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לדבר ממשנתנו: \u0003נפל הבית עליו ועל אביו,\u0004 או \u0003עליו ועל מורישיו\u0004 האחרים, \u0003והיתה עליו,\u0004 על הבן, חובת תשלום ל\u0003כתובת אשה ובעל חוב, יורשי האב אומרים: הבן מת ראשון ואחר כך מת האב, ובעלי חובות אומרים: האב מת ראשון\u0004 ואחר כך מת הבן, ומשום כך יש לנו שיעבוד על מה שירש הבן מאביו.","\u0003ואי סלקא דעתך \"דאיקני\"\u0004 \u0005[ואם עולה על דעתך\u0006 לומר שכשאומר \u0005\"שאקנה\"]\u0006 ו\u0003קנה ומכר, \"דאיקני\"\u0004 \u0005[\"שאקנה\"]\u0006 \u0003קנה והוריש\u0004 — \u0003לא משתעבד,\u0004 הרי \u0003נהי נמי\u0004 \u0005[גם אם נניח]\u0006 שה\u0003אב מית ברישא\u0004 \u0005[מת בראשונה],\u0006 הלא נכס זה שירש הבן מאביו בכלל \u0003\"דאיקני\"\u0004 \u0005[\u0006\"נכסים \u0005שאקנה\"]\u0006 \u0003הוא,\u0004 שהרי הגיעו לידו לאחר ההלוואה, ומשמע איפוא שיש דרך לשעבד נכסים עתידיים, בדרך של \"דאיקני\"!","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב נחמן, זעירא\u0004 (ר' זירא) \u0003חברין\u0004 \u0005[חברנו]\u0006 \u0003תרגמה\u0004 \u0005[הסביר אותה\u0006 כך\u0005]:\u0006 הטעם שבעלי החוב יכולים לגבות במקרה כזה אינו משום שעבוד \"דאיקני\", אלא מפני ש\u0003מצוה על היתומים לפרוע חובת אביהן,\u0004 ואין מכאן כלל ראיה למקרה רגיל של \"דאיקני\", כשקנה ומכר. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב אשי:\u0004 לפי הסבר זה שההתחייבות לשלם אינה מכוח השטר שביד המלוה, אם כן \u0003מלוה על פה הוא, ורב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מלוה על פה\u0004 — \u0003אינו גובה לא מן היורשין ולא מן הלקוחות!\u0004"],["\u0003אלא הא מני\u0004 \u0005[\u0006משנתנו \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 —שיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: אדם מקנה דבר שלא בא לעולם\u0004 ואין להביא מכאן ראיה לשיטת חכמים.","\u0003אמר רב יעקב מנהר פקוד משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבינא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו במשנה זו: \u0003שטרי חוב המוקדמין\u0004 שהזמן הכתוב בהם הוא מוקדם מזמן ההלוואה — \u0003פסולין, והמאוחרין\u0004 שהזמן הכתוב בהם הוא מאוחר מזמן ההלוואה — \u0003כשרין.\u0004","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 שאם כותב \u0003\"דאיקני\"\u0004 ו\u0003קנה ומכר,\u0004 וכן \u0003\"דאיקני\"\u0004 ו\u0003קנה והוריש\u0004 — מה שמכר או הוריש \u0003לא משתעבד,\u0004 שטרי חוב \u0003מאוחרין אמאי\u0004 \u0005[מדוע]\u0006 \u0003כשרין?\u0004 והלא פעמים \u0003\"דאיקני\" הוא!\u0004 שאם יקנה הלווה נכסים לאחר זמן ההלוואה (ולפני זמן התאריך שבשטר) ויחזור וימכרם, הרי לפי הכתוב בשטר — יטרוף אותם המלוה שלא כדין, שהרי הם בכלל \"דאיקני\" ואינם משועבדים לו כלל!","ודוחים: \u0003הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 — כשיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: אדם מקנה דבר שלא בא לעולם,\u0004 ולשיטתו כאמור, אם כתב \"דאיקני\" — משתעבדים הנכסים שיקנה בעתיד, וגם אלו שימכור","\u0003. אמר רב משרשיא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה לדבר ממה ששנינו שעבור חובות מסויימים אין גובים מנכסים משועבדים, ואחד מהם הוא שבח הקרקעות, והסבירו בברייתא: \u0003לשבח קרקעות כיצד? הרי שמכר שדה לחבירו ו\u0004הקונה \u0003השביחה, ובא בעל חוב וטרפה\u0004 מן הקונה, \u0003כשהוא\u0004 (הקונה) \u0003גובה\u0004 ממי שמכר לו — \u0003גובה את הקרן\u0004 גם \u0003מנכסין משועבדין\u0004 של המוכר, שמכר לאחרים. \u0003ו\u0004אילו \u0003את השבח\u0004 שהוא עצמו השביח, גובה רק \u0003מנכסין בני חורין\u0004 שביד המוכר.","\u0003ואי סלקא דעתך\u0004 \u0005[ו\u0006אולם \u0005אם עולה על דעתך\u0006 לומר\u0005]\u0006 שאם כותב \u0003\"דאיקני\"\u0004 \u0005[\"שאקנה\"]\u0006 ו\u0003קנה\u0004 \u0003ומכר,\u0004 וכן אם אמר \u0003\"דאיקני\"\u0004 \u0005[\"שאקנה\"]\u0006 ו\u0003קנה והוריש\u0004 — \u0003לא משתעבד,\u0004 אם כן, אפילו אם כתב לו \"דאיקני\", \u0003בעל חוב אמאי גובה שבחא\u0004 \u0005[מדוע\u0006 הוא \u0005גובה\u0006 את \u0005השבח]\u0006 מאותו שדה שביד הקונה? והרי שבח זה לא היה בזמן ההלוואה, ולא נשתעבד למלוה!","ודוחים: \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 — שיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: אדם מקנה דבר שלא בא לעולם.\u0004 אבל לשיטת חכמים אכן יש לשאול מה יהא הדין.","ושואלים עוד: \u0003אם תמצא לומר\u0004 שהאומר \u0003\"דאיקני\"\u0004 \u0005[\"שאקנה\"]\u0006 \u0003קנה ומכר, \"דאיקני\"\u0004 \u0005[\"שאקנה\"]\u0006 ו\u0003קנה והוריש לא משתעבד\u0004 — \u0003הא\u0004 \u0005[זה]\u0006 במקרה שיובא להלן \u0003לא משתעבד,\u0004 ואין מקום לשאלה הבאה. אבל \u0003אם תמצא לומר\u0004 שהוא \u0003משתעבד,\u0004 יש לשאול: אם \u0003לוה\u0004 מאדם אחד וחזר \u0003ולוה\u0004 מאחר, וכתב לשניהם שהוא משעבד נכסים שיקנה, \u0003וחזר וקנה, מהו?\u0004 האם \u0003לקמא\u0004 \u0005[לראשון\u0006 שבהם\u0005]\u0006 הוא \u0003משתעבד או לבתרא\u0004 \u0005[לאחרון]\u0006 הוא \u0003משתעבד?\u0004","\u0003אמר רב נחמן: הא מילתא איבעיא לן\u0004 \u0005[דבר זה נשאל לנו],\u0006 \u0003ושלחו מתם\u0004 \u0005[משם,\u0006 מארץ ישראל\u0005],\u0006 הלכה בענין זה: \u0003ראשון\u0004 שבהם \u0003קנה,\u0004 לפי ששיעבודו קודם. \u0003רב הונא אמר: יחלוקו\u0004 שני המלוים. \u0003וכן תני\u0004 \u0005[שנה]\u0006 \u0003רבה בר אבוה: יחלוקו. אמר רבינא, מהדורא קמא\u0004 \u0005[\u0006ב\u0005מחזור הראשון]\u0006 של \u0003רב אשי,\u0004 בפעם הראשונה שלימד את התלמוד כולו, \u0003אמר לן\u0004 \u0005[לנו]:\u0006 \u0003ראשון קנה,\u0004 ואילו ב\u0003מהדורא בתרא\u0004 \u0005[\u0006ב\u0005מחזור האחרון]\u0006 של \u0003רב אשי,\u0004 כשחזר ולימד את התלמוד בפעם השניה, \u0003אמר לן\u0004 \u0005[לנו]:\u0006 \u0003יחלוקו.\u0004 ומסכמים: \u0003והלכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003יחלוקו.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו \u0005:\u0006 \u0003לשבח קרקעות כיצד? הרי שמכר שדה לחבירו והשביחה, ובא בעל חוב וטרפה, כשהוא\u0004 הקונה \u0003גובה\u0004 מן המוכר עבור מה שנלקח ממנו — \u0003גובה את הקרן מנכסין משועבדין\u0004 שמכרם המוכר, \u0003ואת השבח מנכסין בני חורין. ואם איתא\u0004 \u0005[יש]\u0006 מקום לשיטה זו, שכל נושה חולק עם חבירו בנכסים שקנה החייב — הרי במקרה זה השבח שהשביחו נכסים אלו לאחר המכירה משועבד גם לבעל החוב, ולא רק לקונה, ואם כן \u0003חצי שבח מבעי ליה\u0004 \u0005[צריך היה לו\u0006 לקחת\u0005]\u0006 ולא את הכל!","ומשיבים: \u0003מאי\u0004 \u0005[מהו\u0006 פירוש\u0005]\u0006 \u0003\"גובה\" נמי דקתני\u0004 \u0005[גם כן ששנינו\u0006 שם\u0005]?\u0006 — לא כל השבח כולו גובה מן הקונה, אלא \u0003חצי שבח\u0004 בלבד."]]};
